window.__tinePages=[{"favorite":false,"journal":false,"slug":"feature-showcase","title":"Feature showcase"},{"favorite":false,"journal":false,"slug":"features-formulas","title":"Features/Formulas"},{"favorite":false,"journal":false,"slug":"features-managed-sync","title":"Features/Managed sync"},{"favorite":false,"journal":false,"slug":"features-pdf-annotation","title":"Features/PDF annotation"},{"favorite":false,"journal":false,"slug":"features-plugins","title":"Features/Plugins"},{"favorite":false,"journal":false,"slug":"features-quick-capture","title":"Features/Quick capture"},{"favorite":false,"journal":false,"slug":"features-sheets","title":"Features/Sheets"},{"favorite":false,"journal":false,"slug":"features-tips-shortcuts","title":"Features/Tips & shortcuts"},{"favorite":false,"journal":false,"slug":"project-roadmap","title":"Project/Roadmap"},{"favorite":false,"journal":false,"slug":"reference-files-external-edits-and-backups","title":"Reference/Files, external edits, and backups"},{"favorite":false,"journal":false,"slug":"reference-journals-tasks-and-scheduling","title":"Reference/Journals, tasks, and scheduling"},{"favorite":false,"journal":false,"slug":"reference-pages-links-references-and-search","title":"Reference/Pages, links, references, and search"},{"favorite":false,"journal":false,"slug":"reference-platforms-and-mobile","title":"Reference/Platforms and mobile"},{"favorite":false,"journal":false,"slug":"reference-troubleshooting-and-recovery","title":"Reference/Troubleshooting and recovery"},{"favorite":false,"journal":false,"slug":"start-bring-an-existing-graph","title":"Start/Bring an existing graph"},{"favorite":false,"journal":false,"slug":"start-where-things-are","title":"Start/Where things are"},{"favorite":false,"journal":false,"slug":"tine-guide","title":"Tine Guide"},{"favorite":true,"journal":false,"slug":"welcome-to-tine","title":"Welcome to Tine"},{"favorite":false,"journal":false,"slug":"workflows-capture-and-plan-your-day","title":"Workflows/Capture and plan your day"},{"favorite":false,"journal":false,"slug":"workflows-extend-tine","title":"Workflows/Extend Tine"},{"favorite":false,"journal":false,"slug":"workflows-find-and-revisit","title":"Workflows/Find and revisit"},{"favorite":false,"journal":false,"slug":"workflows-keep-context-visible","title":"Workflows/Keep context visible"},{"favorite":false,"journal":false,"slug":"workflows-research-a-document","title":"Workflows/Research a document"},{"favorite":false,"journal":false,"slug":"workflows-structure-repeated-information","title":"Workflows/Structure repeated information"}];
window.__tineBlocks=[{"anchor":"b0","slug":"feature-showcase","text":"This page exercises every Logseq page-level feature Tine knows about, so you can see exactly how each one renders — and where we're still rough. It's ordinary Logseq Markdown; the same file opens unchanged in Logseq.","title":"Feature showcase"},{"anchor":"b1","slug":"feature-showcase","text":"1 — Inline text formatting","title":"Feature showcase"},{"anchor":"b2","slug":"feature-showcase","text":"Bold, italic, also italic, strikethrough, inline code, highlight, and also highlight.","title":"Feature showcase"},{"anchor":"b3","slug":"feature-showcase","text":"A mix in one line: a bold code span, an italic link, and a struck highlight.","title":"Feature showcase"},{"anchor":"b4","slug":"feature-showcase","text":"Raw inline HTML renders (sanitized to a safe allowlist): , , + , , and / . Scripts and event handlers (onerror=, <script>) are stripped.","title":"Feature showcase"},{"anchor":"b5","slug":"feature-showcase","text":"Logseq Hiccup vectors render through the same safe-markup boundary in Tine and in static HTML export:","title":"Feature showcase"},{"anchor":"b6","slug":"feature-showcase","text":"[:span {:class \"hiccup-sample\"} \"Hiccup \" [:strong \"markup\"]]","title":"Feature showcase"},{"anchor":"b7","slug":"feature-showcase","text":"Parity note: a tag glued to a word — H<sub>2</sub>O, mc<sup>2</sup> — stays literal in Logseq too (mldoc only starts inline HTML at a word boundary), and so do the Markdown carets x^2^ / H~2~O. For a glued subscript, use math: E = mc^2, H_2O.","title":"Feature showcase"},{"anchor":"b8","slug":"feature-showcase","text":"2 — Links & references","title":"Feature showcase"},{"anchor":"b9","slug":"feature-showcase","text":"Page link: Welcome to Tine · tag: #demo · namespaced page: Features/Quick capture.","title":"Feature showcase"},{"anchor":"b10","slug":"feature-showcase","text":"External link: the Logseq docs · bare URL: https://logseq.com · autolinked email: .","title":"Feature showcase"},{"anchor":"b11","slug":"feature-showcase","text":"Labelled page link: read the welcome.","title":"Feature showcase"},{"anchor":"00000000-0000-4000-8000-00000000feed","slug":"feature-showcase","text":"This block is a reference target.","title":"Feature showcase"},{"anchor":"b12","slug":"feature-showcase","text":"Block reference to it: .","title":"Feature showcase"},{"anchor":"b13","slug":"feature-showcase","text":"3 — Headings","title":"Feature showcase"},{"anchor":"b14","slug":"feature-showcase","text":"Heading 1","title":"Feature showcase"},{"anchor":"b15","slug":"feature-showcase","text":"Heading 2","title":"Feature showcase"},{"anchor":"b16","slug":"feature-showcase","text":"Heading 3","title":"Feature showcase"},{"anchor":"b17","slug":"feature-showcase","text":"Heading 4","title":"Feature showcase"},{"anchor":"b18","slug":"feature-showcase","text":"Heading 5","title":"Feature showcase"},{"anchor":"b19","slug":"feature-showcase","text":"Heading 6","title":"Feature showcase"},{"anchor":"b20","slug":"feature-showcase","text":"4 — Lists & nesting","title":"Feature showcase"},{"anchor":"b21","slug":"feature-showcase","text":"Parent bullet","title":"Feature showcase"},{"anchor":"b22","slug":"feature-showcase","text":"Child bullet","title":"Feature showcase"},{"anchor":"b23","slug":"feature-showcase","text":"Grandchild bullet","title":"Feature showcase"},{"anchor":"b24","slug":"feature-showcase","text":"Second child with a formatted tail","title":"Feature showcase"},{"anchor":"b25","slug":"feature-showcase","text":"Numbered list (logseq order):","title":"Feature showcase"},{"anchor":"b26","slug":"feature-showcase","text":"First","title":"Feature showcase"},{"anchor":"b27","slug":"feature-showcase","text":"Second","title":"Feature showcase"},{"anchor":"b28","slug":"feature-showcase","text":"Third","title":"Feature showcase"},{"anchor":"b29","slug":"feature-showcase","text":"5 — Block content types","title":"Feature showcase"},{"anchor":"b30","slug":"feature-showcase","text":"A blockquote. Logseq renders this with a left rule and muted text.","title":"Feature showcase"},{"anchor":"b31","slug":"feature-showcase","text":"Fenced code block with language highlighting:","title":"Feature showcase"},{"anchor":"b32","slug":"feature-showcase","text":"fn main() { let greeting = \"hello from Tine\"; println!(\"{greeting}\"); }","title":"Feature showcase"},{"anchor":"b33","slug":"feature-showcase","text":"A Markdown table:","title":"Feature showcase"},{"anchor":"b34","slug":"feature-showcase","text":"Feature Logseq Tine Tables yes ? Math yes ?","title":"Feature showcase"},{"anchor":"b35","slug":"feature-showcase","text":"Horizontal rule follows:","title":"Feature showcase"},{"anchor":"b37","slug":"feature-showcase","text":"Inline math E = mc^2 and display math:","title":"Feature showcase"},{"anchor":"b38","slug":"feature-showcase","text":"\\int_{-\\infty}^{\\infty} e^{-x^2}\\,dx = \\sqrt{\\pi}","title":"Feature showcase"},{"anchor":"b39","slug":"feature-showcase","text":"An inline image (sized): capture window","title":"Feature showcase"},{"anchor":"b40","slug":"feature-showcase","text":"6 — Tasks, priorities, scheduling","title":"Feature showcase"},{"anchor":"b41","slug":"feature-showcase","text":"A plain task marker","title":"Feature showcase"},{"anchor":"b42","slug":"feature-showcase","text":"A task in progress","title":"Feature showcase"},{"anchor":"b43","slug":"feature-showcase","text":"A finished task","title":"Feature showcase"},{"anchor":"b44","slug":"feature-showcase","text":"Deferred (now-workflow marker)","title":"Feature showcase"},{"anchor":"b45","slug":"feature-showcase","text":"Active (now-workflow marker)","title":"Feature showcase"},{"anchor":"b46","slug":"feature-showcase","text":"Blocked on someone else","title":"Feature showcase"},{"anchor":"b47","slug":"feature-showcase","text":"Abandoned task","title":"Feature showcase"},{"anchor":"b48","slug":"feature-showcase","text":"High-priority task","title":"Feature showcase"},{"anchor":"b49","slug":"feature-showcase","text":"Medium-priority task","title":"Feature showcase"},{"anchor":"b50","slug":"feature-showcase","text":"Low-priority task","title":"Feature showcase"},{"anchor":"b51","slug":"feature-showcase","text":"A scheduled task","title":"Feature showcase"},{"anchor":"b52","slug":"feature-showcase","text":"A task with a deadline","title":"Feature showcase"},{"anchor":"b53","slug":"feature-showcase","text":"A repeating task","title":"Feature showcase"},{"anchor":"b54","slug":"feature-showcase","text":"A task with a logbook (time tracking)","title":"Feature showcase"},{"anchor":"b55","slug":"feature-showcase","text":"7 — Block properties","title":"Feature showcase"},{"anchor":"b56","slug":"feature-showcase","text":"A block carrying its own properties.","title":"Feature showcase"},{"anchor":"b57","slug":"feature-showcase","text":"8 — Embeds","title":"Feature showcase"},{"anchor":"b58","slug":"feature-showcase","text":"Page embed of another demo page:","title":"Feature showcase"},{"anchor":"b60","slug":"feature-showcase","text":"Block embed of the reference target above:","title":"Feature showcase"},{"anchor":"b62","slug":"feature-showcase","text":"9 — Queries","title":"Feature showcase"},{"anchor":"b63","slug":"feature-showcase","text":"Simple query — every TODO task in this graph:","title":"Feature showcase"},{"anchor":"b65","slug":"feature-showcase","text":"Simple query — blocks referencing a page:","title":"Feature showcase"},{"anchor":"b67","slug":"feature-showcase","text":"Query by priority:","title":"Feature showcase"},{"anchor":"b69","slug":"feature-showcase","text":"Compound query (and / or / not) — TODO tasks that are also high priority:","title":"Feature showcase"},{"anchor":"b71","slug":"feature-showcase","text":"10 — Macros, renderers & callouts","title":"Feature showcase"},{"anchor":"b72","slug":"feature-showcase","text":"Video embed:","title":"Feature showcase"},{"anchor":"b73","slug":"feature-showcase","text":"Namespace macro:","title":"Feature showcase"},{"anchor":"b74","slug":"feature-showcase","text":"A NOTE callout:","title":"Feature showcase"},{"anchor":"b75","slug":"feature-showcase","text":"Callouts (admonitions) group a highlighted aside. This is a NOTE.","title":"Feature showcase"},{"anchor":"b76","slug":"feature-showcase","text":"A footnote reference in a sentence.","title":"Feature showcase"},{"anchor":"b77","slug":"feature-showcase","text":"And here is the footnote body.","title":"Feature showcase"},{"anchor":"b78","slug":"feature-showcase","text":"Create one yourself","title":"Feature showcase"},{"anchor":"b79","slug":"feature-showcase","text":"1. Make a scratch page and add one bullet per construct you want to test: links, tables, code, tasks, embeds, queries, and callouts.","title":"Feature showcase"},{"anchor":"b80","slug":"feature-showcase","text":"2. Keep each example small and label it with a heading so it is easy to scan.","title":"Feature showcase"},{"anchor":"b81","slug":"feature-showcase","text":"3. Add page properties such as title:: or icon:: at the top when the whole page needs metadata.","title":"Feature showcase"},{"anchor":"b82","slug":"feature-showcase","text":"4. What you should see: each example renders live while staying ordinary Logseq Markdown.","title":"Feature showcase"},{"anchor":"b0","slug":"features-formulas","text":"Formulas","title":"Features/Formulas"},{"anchor":"b1","slug":"features-formulas","text":"A formula column is an extra column whose value Tine works out for you from the other columns in the row. You never type the result — Tine recomputes it live, shows it on screen, and never writes it back onto your bullets. Open the same file in Logseq and you just see ordinary bullets with a harmless tine.formula.* property.","title":"Features/Formulas"},{"anchor":"b2","slug":"features-formulas","text":"A formula in action","title":"Features/Formulas"},{"anchor":"b3","slug":"features-formulas","text":"Sketch the outline","title":"Features/Formulas"},{"anchor":"b4","slug":"features-formulas","text":"Write the first draft","title":"Features/Formulas"},{"anchor":"b5","slug":"features-formulas","text":"The plan column is a formula. Tine reads hours from each row and shows focus block or quick task — you never type it, and it updates the moment hours changes.","title":"Features/Formulas"},{"anchor":"b6","slug":"features-formulas","text":"The building blocks","title":"Features/Formulas"},{"anchor":"b7","slug":"features-formulas","text":"Value face — click it to open a picker with these sections:","title":"Features/Formulas"},{"anchor":"b8","slug":"features-formulas","text":"Field — one of your own columns (or type a custom field name).","title":"Features/Formulas"},{"anchor":"b9","slug":"features-formulas","text":"Formula — another formula column on the same table, shown as formula.<name>.","title":"Features/Formulas"},{"anchor":"b10","slug":"features-formulas","text":"Literal — a fixed number, a bit of text, or True / False / Empty.","title":"Features/Formulas"},{"anchor":"b11","slug":"features-formulas","text":"Function — if condition, is empty, now, today.","title":"Features/Formulas"},{"anchor":"b12","slug":"features-formulas","text":"Transform — tweaks like lowercase, trim, round, year, format date, length.","title":"Features/Formulas"},{"anchor":"b13","slug":"features-formulas","text":"IF / THEN / ELSE — pick the if condition function on any value to branch: IF a condition THEN one value ELSE another value.","title":"Features/Formulas"},{"anchor":"b14","slug":"features-formulas","text":"Condition — compare two values with an operator (=, ≠, <, ≤, >, ≥), and join several with AND / OR.","title":"Features/Formulas"},{"anchor":"b15","slug":"features-formulas","text":"</> raw — type it directly","title":"Features/Formulas"},{"anchor":"b16","slug":"features-formulas","text":"The </> raw button at the top-right of the editor switches from clickable faces to a plain text box, where you can type the expression yourself — for example hours * 2 or if(hours > 3, \"focus block\", \"quick task\"). The chips below insert your fields, other formulas, and built-in functions at the cursor. Flip Builder back on whenever the text is something the faces can show again.","title":"Features/Formulas"},{"anchor":"b17","slug":"features-formulas","text":"Honest limits","title":"Features/Formulas"},{"anchor":"b18","slug":"features-formulas","text":"The visual builder handles one level: a single IF/THEN/ELSE, simple comparisons, and a value that is at most one arithmetic step of two simple values (like hours * 2).","title":"Features/Formulas"},{"anchor":"b19","slug":"features-formulas","text":"Anything more nested — a formula inside a THEN branch, or arithmetic of arithmetic like (hours + extra) * 2 — shows up as a small raw box instead of pretty faces. Use </> raw to type those directly; they still evaluate exactly the same, they just do not get a visual face.","title":"Features/Formulas"},{"anchor":"b20","slug":"features-formulas","text":"Formula values are read-only and are never saved onto your rows, so they always reflect the current data and round-trip cleanly back to Logseq.","title":"Features/Formulas"},{"anchor":"b21","slug":"features-formulas","text":"Create one yourself — formula","title":"Features/Formulas"},{"anchor":"b22","slug":"features-formulas","text":"1. Make a table (see Features/Sheets) with at least one field to compute from, for example a hours=number column.","title":"Features/Formulas"},{"anchor":"b23","slug":"features-formulas","text":"2. Right-click a table column header — or right-click the table body / open its ⋮ menu — and choose Add formula…. Give it a short lowercase name like plan.","title":"Features/Formulas"},{"anchor":"b24","slug":"features-formulas","text":"3. The visual builder opens. You build the value by clicking faces — no syntax to memorize: pick a field, add a comparison, wrap it in IF / THEN / ELSE. Press Save and a read-only column appears, filling in live.","title":"Features/Formulas"},{"anchor":"b25","slug":"features-formulas","text":"4. Use the </> raw toggle when you would rather type the expression, such as hours * 2.","title":"Features/Formulas"},{"anchor":"b26","slug":"features-formulas","text":"5. To change it later, right-click the formula column and choose Edit formula….","title":"Features/Formulas"},{"anchor":"b27","slug":"features-formulas","text":"6. What you should see: a read-only computed column whose values evaluate live and are never written onto the rows.","title":"Features/Formulas"},{"anchor":"b0","slug":"features-managed-sync","text":"Managed storage & sync","title":"Features/Managed sync"},{"anchor":"b1","slug":"features-managed-sync","text":"Known to be buggy. Tine-managed storage does not yet fully work in our own testing; we're actively working on it. Use it only on a graph you are comfortable testing. Your normal mode is Direct files: Tine reads and writes your existing Markdown or Org graph, and Syncthing, Dropbox, Logseq, and other tools can keep synchronizing those files exactly as before. Nothing changes unless you explicitly enable this mode for one graph.","title":"Features/Managed sync"},{"anchor":"b2","slug":"features-managed-sync","text":"What the opt-in does","title":"Features/Managed sync"},{"anchor":"b3","slug":"features-managed-sync","text":"Tine stores operation history in that graph's .tine-sync/ directory while keeping your Markdown/Org files in place as an editable projection. Logseq and other file-based tools can still read those files; Tine conservatively reconciles outside edits.","title":"Features/Managed sync"},{"anchor":"b4","slug":"features-managed-sync","text":"This is a separate mode, not a replacement for ordinary Syncthing/Dropbox. Do not enable it merely because you already synchronize your graph folders.","title":"Features/Managed sync"},{"anchor":"b5","slug":"features-managed-sync","text":"Current scope","title":"Features/Managed sync"},{"anchor":"b6","slug":"features-managed-sync","text":"Managed storage currently covers page and journal text only. Assets, PDF sidecars, and configuration remain ordinary provider-synchronized files.","title":"Features/Managed sync"},{"anchor":"b7","slug":"features-managed-sync","text":"Setup first makes a safety backup and checks that Tine can reconstruct the same Markdown/Org tree. If that cannot be proven, it stops instead of changing graph authority.","title":"Features/Managed sync"},{"anchor":"b8","slug":"features-managed-sync","text":"Review a detected group deletion","title":"Features/Managed sync"},{"anchor":"b9","slug":"features-managed-sync","text":"This safety surface belongs only to a graph using Tine-managed storage. Direct-files graphs keep their ordinary file and snapshot recovery paths.","title":"Features/Managed sync"},{"anchor":"b10","slug":"features-managed-sync","text":"Four deleted pages together become a Tier 2 sweep. A deletion reaching at least 10% of the graph's pages (rounded up), or 50 pages when that is lower, becomes Tier 3. Tier 1 stays quiet. A Tier 3 sweep also pauses propagation for about five minutes so another device is less likely to carry a mass deletion onward before you can review it.","title":"Features/Managed sync"},{"anchor":"b11","slug":"features-managed-sync","text":"Tine shows a warning and keeps a Deleted pages dock with the sweep's member pages and live action status. Closing either the warning or the panel makes no decision and deletes no sweep record.","title":"Features/Managed sync"},{"anchor":"b12","slug":"features-managed-sync","text":"Choose Restore to revive every member from its accepted predecessor state, Re-apply to accept and re-author the deletion against the current state, or Keep deletion to deliberately retain the accepted deletion. These are the only actions that dispose the sweep.","title":"Features/Managed sync"},{"anchor":"b13","slug":"features-managed-sync","text":"Restore may run in several durable chunks. The panel shows its progress; if it fails, it keeps the recorded cause and offers Run Restore again to resume through the same backend recovery path.","title":"Features/Managed sync"},{"anchor":"b14","slug":"features-managed-sync","text":"What you should see: the dock remains until you make an explicit choice, and then keeps the completed disposition visible as history. See Reference/Troubleshooting and recovery for the same steps in recovery form.","title":"Features/Managed sync"},{"anchor":"b15","slug":"features-managed-sync","text":"Try it on a test graph","title":"Features/Managed sync"},{"anchor":"b16","slug":"features-managed-sync","text":"1. Open Settings (t s) → Backups & recovery → Storage & sync.","title":"Features/Managed sync"},{"anchor":"b17","slug":"features-managed-sync","text":"2. Read the Known to be buggy warning, then choose Enable Tine-managed storage... for a graph you are comfortable testing.","title":"Features/Managed sync"},{"anchor":"b18","slug":"features-managed-sync","text":"3. Wait for setup to finish. Your Markdown/Org files remain beside the new .tine-sync/ data; do not edit the internal sync directory yourself.","title":"Features/Managed sync"},{"anchor":"b19","slug":"features-managed-sync","text":"4. To prepare a second test device, first let your existing provider deliver the same test graph folder there. Then use Set up sync with another device... on the first device and Join this synced graph... on the other one. Tine verifies that both devices are joining the same graph history.","title":"Features/Managed sync"},{"anchor":"b20","slug":"features-managed-sync","text":"5. What you should see: Direct files remains available for ordinary graphs, and managed storage is enabled only for the graph where you chose it.","title":"Features/Managed sync"},{"anchor":"b21","slug":"features-managed-sync","text":"Return to Direct files","title":"Features/Managed sync"},{"anchor":"b22","slug":"features-managed-sync","text":"The same panel offers Return to Direct files when Tine can first preserve complete recovery state. If it says that safety could not be verified, leave the graph alone and resolve that state rather than forcing a file-mode switch.","title":"Features/Managed sync"},{"anchor":"b0","slug":"features-pdf-annotation","text":"PDF annotation","title":"Features/PDF annotation"},{"anchor":"b1","slug":"features-pdf-annotation","text":"Open a PDF that lives in your graph's assets/ (or drop one in). On desktop it opens as a normal tab in a companion pane, keeping the page you came from visible; on a phone it opens in the same one-pane history.","title":"Features/PDF annotation"},{"anchor":"b2","slug":"features-pdf-annotation","text":"Select text in the PDF to highlight it; click a highlight again to change its color.","title":"Features/PDF annotation"},{"anchor":"b3","slug":"features-pdf-annotation","text":"Hold Shift while dragging a rectangle on Linux or Windows, or Command on macOS, then choose a color to clip a figure or equation as an image highlight. Dismissing the color chooser writes nothing.","title":"Features/PDF annotation"},{"anchor":"b4","slug":"features-pdf-annotation","text":"Use the reader toolbar to choose a persistent Light, Warm, or Dark page theme, and open Outline to navigate a PDF's nested table of contents.","title":"Features/PDF annotation"},{"anchor":"b5","slug":"features-pdf-annotation","text":"Every highlight becomes a block on a notes page named after the PDF, so you can write underneath it, link it, and reference it like any other bullet — and each note jumps straight back to its spot in the document.","title":"Features/PDF annotation"},{"anchor":"b6","slug":"features-pdf-annotation","text":"It's how you turn a paper into linked, searchable notes without ever leaving Tine.","title":"Features/PDF annotation"},{"anchor":"b7","slug":"features-pdf-annotation","text":"For the end-to-end path from dropping a PDF in to quoting its passages and sharing the result, see Workflows/Research a document.","title":"Features/PDF annotation"},{"anchor":"b8","slug":"features-pdf-annotation","text":"Create one yourself","title":"Features/PDF annotation"},{"anchor":"b9","slug":"features-pdf-annotation","text":"1. Put a PDF in your graph's assets/ folder, or drop it into a page.","title":"Features/PDF annotation"},{"anchor":"b10","slug":"features-pdf-annotation","text":"2. Open the PDF from its asset link. On desktop, drag its tab to any existing pane or drop it on a pane edge to put it in a new split or quadrant. On a phone, use Back to return to the page that contained the link.","title":"Features/PDF annotation"},{"anchor":"b11","slug":"features-pdf-annotation","text":"3. Select text to create a highlight, or hold Shift (Linux/Windows) or Command (macOS) and drag a rectangle for an area highlight, then choose its color.","title":"Features/PDF annotation"},{"anchor":"b12","slug":"features-pdf-annotation","text":"4. Write notes under the generated highlight blocks.","title":"Features/PDF annotation"},{"anchor":"b13","slug":"features-pdf-annotation","text":"5. What you should see: each highlight is a normal block that links back to the exact PDF location.","title":"Features/PDF annotation"},{"anchor":"b0","slug":"features-plugins","text":"Plugins","title":"Features/Plugins"},{"anchor":"b1","slug":"features-plugins","text":"Tine plugins are capability-limited WebAssembly guests. They are not Logseq or Obsidian plugins and cannot use those apps' plugin APIs.","title":"Features/Plugins"},{"anchor":"b2","slug":"features-plugins","text":"Plugins cannot directly access the DOM, Tauri, files, processes, the network, or arbitrary graph paths. Tine owns the commands, slash actions, decorations, settings controls, and any narrowly authorized block edit that a plugin can request.","title":"Features/Plugins"},{"anchor":"b3","slug":"features-plugins","text":"Workflows/Extend Tine walks the hands-on install → review → enable → disable path; this page remains the detailed reference.","title":"Features/Plugins"},{"anchor":"b4","slug":"features-plugins","text":"Browse and install","title":"Features/Plugins"},{"anchor":"b5","slug":"features-plugins","text":"Open Settings → Plugins → Browse for the signed community catalogue. Each entry shows its source, supported platforms, declared capabilities, publication review, and a digest-verified safety report.","title":"Features/Plugins"},{"anchor":"b6","slug":"features-plugins","text":"Choose Install on a compatible entry. Local developers can instead choose Install a local package and select its manifest.json and .wasm together.","title":"Features/Plugins"},{"anchor":"b7","slug":"features-plugins","text":"Every version is installed disabled. Open Installed, review its identity and capabilities, then enable it explicitly.","title":"Features/Plugins"},{"anchor":"b8","slug":"features-plugins","text":"Control a plugin","title":"Features/Plugins"},{"anchor":"b9","slug":"features-plugins","text":"Open a plugin's Details or Settings page to change its host-rendered options. Plugins receive only validated scalar values; they do not draw their own settings UI.","title":"Features/Plugins"},{"anchor":"b10","slug":"features-plugins","text":"Disable a plugin at any time without removing it. Uninstall removes only that app-local package version and never changes your graph or notes.","title":"Features/Plugins"},{"anchor":"b11","slug":"features-plugins","text":"Signed revocations are checked before saved plugins start. A revoked version stays disabled even when the live catalogue is temporarily unavailable.","title":"Features/Plugins"},{"anchor":"b12","slug":"features-plugins","text":"Themes","title":"Features/Plugins"},{"anchor":"b13","slug":"features-plugins","text":"Declarative themes live under Settings → Appearance → Themes, separately from executable plugins. They contain validated colors and may select bounded Tine-owned presentation styles rather than running code.","title":"Features/Plugins"},{"anchor":"b14","slug":"features-plugins","text":"A selected token theme remains subordinate to your graph's logseq/custom.css, so your own CSS still wins.","title":"Features/Plugins"},{"anchor":"b15","slug":"features-plugins","text":"Create one yourself","title":"Features/Plugins"},{"anchor":"b16","slug":"features-plugins","text":"1. Open Settings → Plugins → Browse.","title":"Features/Plugins"},{"anchor":"b17","slug":"features-plugins","text":"2. Inspect a plugin's capabilities and safety report, then install it.","title":"Features/Plugins"},{"anchor":"b18","slug":"features-plugins","text":"3. Switch to Installed, open its details, and enable it.","title":"Features/Plugins"},{"anchor":"b19","slug":"features-plugins","text":"4. What you should see: only the host-owned command, slash action, or decoration that the plugin declared; disabling it removes that behavior while leaving your graph readable.","title":"Features/Plugins"},{"anchor":"b20","slug":"features-plugins","text":"For authoring, packaging, API versioning, and registry submission, see the developer guide.","title":"Features/Plugins"},{"anchor":"b0","slug":"features-quick-capture","text":"Global quick-capture","title":"Features/Quick capture"},{"anchor":"b1","slug":"features-quick-capture","text":"A passing thought shouldn't make you switch windows. Bind a desktop shortcut and a small always-on-top capture box pops up over any app — with the full Tine editor — and files what you type straight into your graph. Tine doesn't even need to be focused.","title":"Features/Quick capture"},{"anchor":"b2","slug":"features-quick-capture","text":"What it looks like","title":"Features/Quick capture"},{"anchor":"b3","slug":"features-quick-capture","text":"The quick-capture window — note the optional page-title field at the top","title":"Features/Quick capture"},{"anchor":"b4","slug":"features-quick-capture","text":"Set it up (Linux, one time)","title":"Features/Quick capture"},{"anchor":"b5","slug":"features-quick-capture","text":"Tine listens for a launch with the --capture flag, so bind a global keyboard shortcut in your desktop environment to run tine --capture:","title":"Features/Quick capture"},{"anchor":"b6","slug":"features-quick-capture","text":"GNOME — Settings → Keyboard → View and Customize Shortcuts → Custom Shortcuts → +. Command: tine --capture. Pick a key like Super+N.","title":"Features/Quick capture"},{"anchor":"b7","slug":"features-quick-capture","text":"KDE — System Settings → Shortcuts → Add → Command/URL. Command: tine --capture.","title":"Features/Quick capture"},{"anchor":"b8","slug":"features-quick-capture","text":"Other desktops — add a custom keyboard shortcut that runs tine --capture. Use the binary's full path if it isn't on your PATH.","title":"Features/Quick capture"},{"anchor":"b9","slug":"features-quick-capture","text":"Now press your shortcut from anywhere — the box appears, you type, and it's saved.","title":"Features/Quick capture"},{"anchor":"b10","slug":"features-quick-capture","text":"Where your capture goes","title":"Features/Quick capture"},{"anchor":"b11","slug":"features-quick-capture","text":"Leave the title empty → the text is appended to today's journal. This is the fast path: hotkey, type, done.","title":"Features/Quick capture"},{"anchor":"b12","slug":"features-quick-capture","text":"Type a page title (the field at the top of the window) → it's filed to that page instead, created if it doesn't exist yet. Perfect for \"add this to my Reading notes\" without leaving what you're doing.","title":"Features/Quick capture"},{"anchor":"b13","slug":"features-quick-capture","text":"It's the real editor in there: [[ page links, # tags, / slash commands, and nested bullets all work.","title":"Features/Quick capture"},{"anchor":"b14","slug":"features-quick-capture","text":"Create one yourself","title":"Features/Quick capture"},{"anchor":"b15","slug":"features-quick-capture","text":"1. Open your desktop environment's keyboard-shortcut settings.","title":"Features/Quick capture"},{"anchor":"b16","slug":"features-quick-capture","text":"2. Add a custom shortcut whose command is tine --capture.","title":"Features/Quick capture"},{"anchor":"b17","slug":"features-quick-capture","text":"3. Press the shortcut while another app is focused, then type a quick note.","title":"Features/Quick capture"},{"anchor":"b18","slug":"features-quick-capture","text":"4. Leave the title empty for today's journal, or type a page title to file it there.","title":"Features/Quick capture"},{"anchor":"b19","slug":"features-quick-capture","text":"5. What you should see: the capture box saves real Logseq bullets into your graph without switching windows.","title":"Features/Quick capture"},{"anchor":"b20","slug":"features-quick-capture","text":"Tune the Enter key","title":"Features/Quick capture"},{"anchor":"b21","slug":"features-quick-capture","text":"By default Enter starts a new bullet and Ctrl+Shift+Enter files the capture (so you can jot several lines first). Prefer Enter-to-file? Open Settings and flip Quick-capture: Enter key.","title":"Features/Quick capture"},{"anchor":"b22","slug":"features-quick-capture","text":"The box auto-grows as you type, and it keeps your draft if it loses focus — only Esc or filing it clears the text.","title":"Features/Quick capture"},{"anchor":"b23","slug":"features-quick-capture","text":"Where next","title":"Features/Quick capture"},{"anchor":"b24","slug":"features-quick-capture","text":"Captures land in today's journal or on a page you name — Workflows/Capture and plan your day builds the rest of the daily flow on top. This capture window is a desktop feature; Reference/Platforms and mobile maps what each platform ships.","title":"Features/Quick capture"},{"anchor":"b0","slug":"features-sheets","text":"Sheets","title":"Features/Sheets"},{"anchor":"b1","slug":"features-sheets","text":"Sheets turn ordinary outline branches into 2-D views — tables, boards, and grids. The same file still opens in Logseq as nested bullets with harmless tine.* properties, in Markdown and Org alike.","title":"Features/Sheets"},{"anchor":"b2","slug":"features-sheets","text":"This page starts with the easiest path — viewing bullets you already have — and adds fields, formulas, and query-backed views after.","title":"Features/Sheets"},{"anchor":"b3","slug":"features-sheets","text":"Start from bullets you already have","title":"Features/Sheets"},{"anchor":"b4","slug":"features-sheets","text":"Sheets never move your data: rows are child bullets, columns are their properties, cards are child bullets or blocks a query finds. Nothing is converted or copied.","title":"Features/Sheets"},{"anchor":"b5","slug":"features-sheets","text":"Right-click a parent bullet and choose Show children as → Grid or Table — or type /Grid, /Table, or /Board on that block. To view blocks a query finds instead, type /Query, then run /Table or /Board on the query block.","title":"Features/Sheets"},{"anchor":"b6","slug":"features-sheets","text":"What Tine writes: plain block properties such as tine.view:: table on the view-owning block. Editing a sheet cell writes back into the underlying bullet, so the outline and the sheet always agree.","title":"Features/Sheets"},{"anchor":"b7","slug":"features-sheets","text":"Task table","title":"Features/Sheets"},{"anchor":"b8","slug":"features-sheets","text":"Draft the sheet docs #sheets-demo","title":"Features/Sheets"},{"anchor":"b9","slug":"features-sheets","text":"Polish cell menus #sheets-demo","title":"Features/Sheets"},{"anchor":"b10","slug":"features-sheets","text":"Add aggregate footer #sheets-demo","title":"Features/Sheets"},{"anchor":"b11","slug":"features-sheets","text":"Create one yourself — table","title":"Features/Sheets"},{"anchor":"b12","slug":"features-sheets","text":"1. On a block, type /Table and pick Table (or right-click an existing outline and choose Show children as → Table).","title":"Features/Sheets"},{"anchor":"b13","slug":"features-sheets","text":"2. Use the ghost + Add row and + Add column buttons to build it out. Each row is a child bullet; each column is a property such as owner:: or estimate::, edited right in the cells.","title":"Features/Sheets"},{"anchor":"b14","slug":"features-sheets","text":"3. Right-click a children-backed column header or double-click its name to rename the field and its dependent filter, group, aggregate, and formula references together. Ambiguous or colliding names are refused.","title":"Features/Sheets"},{"anchor":"b15","slug":"features-sheets","text":"4. Drag the right edge of a column header to set its width; double-click that edge to reset the one column. Widths are remembered per field, so they survive a reload and follow the field if you reorder columns. A table wider than the pane scrolls sideways instead of crushing its text.","title":"Features/Sheets"},{"anchor":"b16","slug":"features-sheets","text":"5. Press Tab after editing a cell to commit its value and move to the next cell.","title":"Features/Sheets"},{"anchor":"b17","slug":"features-sheets","text":"6. What you should see: each child bullet becomes a row, and properties become editable table columns.","title":"Features/Sheets"},{"anchor":"b18","slug":"features-sheets","text":"7. Under the hood: the block carries tine.view:: table (with optional tine.fields:: to type columns and tine.col-aggregates:: prop:estimate=sum to total a numeric column in the footer). The ghost buttons write these for you.","title":"Features/Sheets"},{"anchor":"b19","slug":"features-sheets","text":"Typed reading list","title":"Features/Sheets"},{"anchor":"b20","slug":"features-sheets","text":"Bases study","title":"Features/Sheets"},{"anchor":"b21","slug":"features-sheets","text":"CSV import notes","title":"Features/Sheets"},{"anchor":"b22","slug":"features-sheets","text":"Create one yourself — formula","title":"Features/Sheets"},{"anchor":"b23","slug":"features-sheets","text":"1. Start with a table that has a numeric or enum field, for example rating=number.","title":"Features/Sheets"},{"anchor":"b24","slug":"features-sheets","text":"2. Right-click a column header and choose Add formula…, then build the value from the visual faces (or the </> raw box).","title":"Features/Sheets"},{"anchor":"b25","slug":"features-sheets","text":"3. What you should see: a read-only computed column — like effort above, which multiplies each row's rating by 2 — whose values evaluate live and are not written onto the rows.","title":"Features/Sheets"},{"anchor":"b26","slug":"features-sheets","text":"4. For the full walkthrough — the value picker, IF / THEN / ELSE, transforms, and when to reach for </> raw — see Features/Formulas.","title":"Features/Sheets"},{"anchor":"b27","slug":"features-sheets","text":"Task board","title":"Features/Sheets"},{"anchor":"b29","slug":"features-sheets","text":"Create one yourself — query","title":"Features/Sheets"},{"anchor":"b30","slug":"features-sheets","text":"1. Type /Query and create a query for the blocks you want, such as tasks tagged #sheets-demo.","title":"Features/Sheets"},{"anchor":"b31","slug":"features-sheets","text":"2. Keep the query in one block, then run /Table or /Board on that same block to view the results.","title":"Features/Sheets"},{"anchor":"b32","slug":"features-sheets","text":"3. For a board, pick the column axis with the Group by dropdown (described in the board steps below).","title":"Features/Sheets"},{"anchor":"b33","slug":"features-sheets","text":"4. What you should see: query results rendered as a live sheet view — the same demo tasks as in the table above — without copying the source blocks.","title":"Features/Sheets"},{"anchor":"b34","slug":"features-sheets","text":"Create one yourself — board","title":"Features/Sheets"},{"anchor":"b35","slug":"features-sheets","text":"1. On a block, type /Board and pick Board (/Kanban finds it too).","title":"Features/Sheets"},{"anchor":"b36","slug":"features-sheets","text":"2. Choose the column axis with the Group by dropdown in the board header, or right-click and use Group by → to pick State, Tags, Priority, or any field.","title":"Features/Sheets"},{"anchor":"b37","slug":"features-sheets","text":"3. Add child bullets, or run /Board on a query block to board over query results.","title":"Features/Sheets"},{"anchor":"b38","slug":"features-sheets","text":"4. Drag a card between columns (or press Ctrl+←/→) and the grouping field changes on the source block.","title":"Features/Sheets"},{"anchor":"b39","slug":"features-sheets","text":"5. What you should see: cards group into columns while staying normal outline blocks underneath. Group by Tags and a card with several tags appears in each matching column — like the topic board below.","title":"Features/Sheets"},{"anchor":"b40","slug":"features-sheets","text":"6. Under the hood: the dropdown just writes tine.view:: board and tine.group-by:: state (or your chosen axis) for you.","title":"Features/Sheets"},{"anchor":"b41","slug":"features-sheets","text":"Topic board","title":"Features/Sheets"},{"anchor":"b42","slug":"features-sheets","text":"Schema menu polish #schema #sheets-demo","title":"Features/Sheets"},{"anchor":"b43","slug":"features-sheets","text":"Schema menu polish #schema #sheets-demo","title":"Features/Sheets"},{"anchor":"b44","slug":"features-sheets","text":"CSV drop walkthrough #interop #sheets-demo","title":"Features/Sheets"},{"anchor":"b45","slug":"features-sheets","text":"CSV drop walkthrough #interop #sheets-demo","title":"Features/Sheets"},{"anchor":"b46","slug":"features-sheets","text":"Positional grid","title":"Features/Sheets"},{"anchor":"b47","slug":"features-sheets","text":"Area","title":"Features/Sheets"},{"anchor":"b48","slug":"features-sheets","text":"Owner","title":"Features/Sheets"},{"anchor":"b49","slug":"features-sheets","text":"Notes","title":"Features/Sheets"},{"anchor":"b50","slug":"features-sheets","text":"Spec","title":"Features/Sheets"},{"anchor":"b51","slug":"features-sheets","text":"Martin","title":"Features/Sheets"},{"anchor":"b52","slug":"features-sheets","text":"Nested sub-grid","title":"Features/Sheets"},{"anchor":"b53","slug":"features-sheets","text":"Risk","title":"Features/Sheets"},{"anchor":"b54","slug":"features-sheets","text":"Mitigation","title":"Features/Sheets"},{"anchor":"b55","slug":"features-sheets","text":"Scope drift","title":"Features/Sheets"},{"anchor":"b56","slug":"features-sheets","text":"Keep v1 narrow","title":"Features/Sheets"},{"anchor":"b57","slug":"features-sheets","text":"Build","title":"Features/Sheets"},{"anchor":"b58","slug":"features-sheets","text":"Codex","title":"Features/Sheets"},{"anchor":"b59","slug":"features-sheets","text":"Ragged rows are fine","title":"Features/Sheets"},{"anchor":"b60","slug":"features-sheets","text":"Empty middle cell","title":"Features/Sheets"},{"anchor":"b62","slug":"features-sheets","text":"Still round-trips","title":"Features/Sheets"},{"anchor":"b63","slug":"features-sheets","text":"Create one yourself — grid","title":"Features/Sheets"},{"anchor":"b64","slug":"features-sheets","text":"1. On an empty block, type /Grid and pick Grid. Tine seeds one editable cell — just start typing.","title":"Features/Sheets"},{"anchor":"b65","slug":"features-sheets","text":"2. Grow it by its edges: hover the grid and click the + on the right edge for a new column, or the + on the bottom edge for a new row. Drag row or cell bullets to reshape it; the grid follows the tree.","title":"Features/Sheets"},{"anchor":"b66","slug":"features-sheets","text":"3. What you should see: a live grid whose cells are still ordinary Logseq bullets — including ragged rows and, above, a whole grid nested in one cell.","title":"Features/Sheets"},{"anchor":"b67","slug":"features-sheets","text":"4. Under the hood: the block just carries tine.view:: grid (plus optional tine.header:: true for a label row and tine.col-widths::). You never have to type those by hand.","title":"Features/Sheets"},{"anchor":"b68","slug":"features-sheets","text":"Honest limits","title":"Features/Sheets"},{"anchor":"b69","slug":"features-sheets","text":"Formula columns are derived: computed live, never written onto the rows.","title":"Features/Sheets"},{"anchor":"b70","slug":"features-sheets","text":"Board cards move between columns, but not within one. page columns are read-only.","title":"Features/Sheets"},{"anchor":"b71","slug":"features-sheets","text":"A board grouped by a formula axis is read-only — moving a card cannot rewrite a computed value.","title":"Features/Sheets"},{"anchor":"b0","slug":"features-tips-shortcuts","text":"Tips & shortcuts","title":"Features/Tips & shortcuts"},{"anchor":"b1","slug":"features-tips-shortcuts","text":"A quick tour of the things that aren't obvious on day one. (Shortcuts are remappable in Settings.)","title":"Features/Tips & shortcuts"},{"anchor":"b2","slug":"features-tips-shortcuts","text":"Find anything — Ctrl+K","title":"Features/Tips & shortcuts"},{"anchor":"b3","slug":"features-tips-shortcuts","text":"Ctrl+K opens the quick switcher: jump to a page, search the text of any block, or run a command — all from one box. Ctrl+Shift+P opens the command palette (commands only).","title":"Features/Tips & shortcuts"},{"anchor":"b4","slug":"features-tips-shortcuts","text":"Use Ctrl+Shift+K to search only the focused page, including children hidden under folded bullets. In the ordinary Ctrl+K switcher, press Shift+Enter on a page or block to send it to the right sidebar without leaving your current page.","title":"Features/Tips & shortcuts"},{"anchor":"b5","slug":"features-tips-shortcuts","text":"Use Search syntax for phrases, alternatives, exclusions, and regular expressions. Choose Open search tab to keep the complete search in a graph-specific tab instead of choosing only one hit.","title":"Features/Tips & shortcuts"},{"anchor":"b6","slug":"features-tips-shortcuts","text":"That result tab can switch between Search, List, Table, and Board without changing what matched. Use Name this search to save it as a page and Save page when the search is worth keeping: Tine turns it into an ordinary query page in your graph. Filters / Advanced handles friendly fields and date ranges; Edit as visual query opens the deeper visual editor when needed.","title":"Features/Tips & shortcuts"},{"anchor":"b7","slug":"features-tips-shortcuts","text":"Page-title matching keeps exact, prefix, substring, and fuzzy results in that order. Repeated choices may break ties inside one class using device-local history; Settings → Editor → Learn Ctrl+K choices disables or resets it.","title":"Features/Tips & shortcuts"},{"anchor":"b8","slug":"features-tips-shortcuts","text":"For a task-first tour of finding things and keeping searches, see Workflows/Find and revisit; for the exact rules, Reference/Pages, links, references, and search.","title":"Features/Tips & shortcuts"},{"anchor":"b9","slug":"features-tips-shortcuts","text":"Follow a link without the mouse — Ctrl+O","title":"Features/Tips & shortcuts"},{"anchor":"b10","slug":"features-tips-shortcuts","text":"With the caret inside a [[link]] or a #tag, Ctrl+O opens that page and Ctrl+Shift+O opens it in the right sidebar. This works while you are editing, so you can follow a name you just typed without reaching for the mouse.","title":"Features/Tips & shortcuts"},{"anchor":"b11","slug":"features-tips-shortcuts","text":"A link whose page does not exist yet is drawn dimmed with a dotted underline. It still works — opening it creates the page — but you can see before clicking that it will start empty. Tags are left alone, since a tag with no page of its own is perfectly normal.","title":"Features/Tips & shortcuts"},{"anchor":"b12","slug":"features-tips-shortcuts","text":"Create one yourself","title":"Features/Tips & shortcuts"},{"anchor":"b13","slug":"features-tips-shortcuts","text":"1. Press Ctrl+K.","title":"Features/Tips & shortcuts"},{"anchor":"b14","slug":"features-tips-shortcuts","text":"2. Type part of a page name, a block phrase, or a command such as Open Guide.","title":"Features/Tips & shortcuts"},{"anchor":"b15","slug":"features-tips-shortcuts","text":"3. Press Enter on the highlighted result.","title":"Features/Tips & shortcuts"},{"anchor":"b16","slug":"features-tips-shortcuts","text":"4. What you should see: Tine jumps to the page/block or runs the command without leaving your graph.","title":"Features/Tips & shortcuts"},{"anchor":"b17","slug":"features-tips-shortcuts","text":"Slash commands — /","title":"Features/Tips & shortcuts"},{"anchor":"b18","slug":"features-tips-shortcuts","text":"Type / at the start of a bullet for a menu: tasks, headings, a code block, a /calc live calculator, dates (Scheduled / Deadline), callouts, queries, a math block, asset upload, and more. /Code block opens a language picker; typing a language after an opening backtick or tilde fence offers the same completion.","title":"Features/Tips & shortcuts"},{"anchor":"b19","slug":"features-tips-shortcuts","text":"Tabs","title":"Features/Tips & shortcuts"},{"anchor":"b20","slug":"features-tips-shortcuts","text":"Middle-click any bullet, page, or search result to open it in a background tab. Double-click a tab to pin it, drag to reorder, Ctrl+W to close. Your tabs come back next launch.","title":"Features/Tips & shortcuts"},{"anchor":"b21","slug":"features-tips-shortcuts","text":"When a pane has more tabs than fit, use its tab-overview button to see every full title, activate or pin a tab, close it, or reorder it with the drag handle / Alt+Up/Down without guessing from truncated labels.","title":"Features/Tips & shortcuts"},{"anchor":"b22","slug":"features-tips-shortcuts","text":"For arranging tabs with the sidebars and split panes into a working layout — and saving it as a workspace — see Workflows/Keep context visible; Start/Where things are maps the places first.","title":"Features/Tips & shortcuts"},{"anchor":"b23","slug":"features-tips-shortcuts","text":"The sidebars","title":"Features/Tips & shortcuts"},{"anchor":"b24","slug":"features-tips-shortcuts","text":"t l toggles the left sidebar — journals, favorites, recents, all pages, and a namespace tree. Favorites and Recent can be folded independently; + New group arranges favorites into collapsible labels, and dragging left/right lifts or nests rows.","title":"Features/Tips & shortcuts"},{"anchor":"b25","slug":"features-tips-shortcuts","text":"t r toggles the right sidebar; Shift-click any bullet's dot to open it there and keep it beside your work. Each right-sidebar item can be folded independently, and its menu can collapse, expand, or close them all.","title":"Features/Tips & shortcuts"},{"anchor":"b26","slug":"features-tips-shortcuts","text":"On a phone-width window (below 640 px), either sidebar opens over the page. Tap the shaded outside edge, use the close button, press Esc, or press Android Back to return to the page. Wider tablet and desktop windows keep the ordinary persistent, resizable sidebars.","title":"Features/Tips & shortcuts"},{"anchor":"b27","slug":"features-tips-shortcuts","text":"Click the vertical outline guide below a bullet to expand its complete descendant subtree when anything inside is folded, or collapse all of those descendants when everything is open. The bullet itself keeps its ordinary one-level action.","title":"Features/Tips & shortcuts"},{"anchor":"b28","slug":"features-tips-shortcuts","text":"Focus mode & dimming — t f / t b","title":"Features/Tips & shortcuts"},{"anchor":"b29","slug":"features-tips-shortcuts","text":"t f (focus mode) hides the sidebars and toolbar so the screen is just your text; layered Esc steps back out.","title":"Features/Tips & shortcuts"},{"anchor":"b30","slug":"features-tips-shortcuts","text":"t b (dim inactive blocks) fades everything except the bullet you're editing — a typewriter-style spotlight. Use it on its own, or let focus mode turn it on for you.","title":"Features/Tips & shortcuts"},{"anchor":"b31","slug":"features-tips-shortcuts","text":"Page width — t w","title":"Features/Tips & shortcuts"},{"anchor":"b32","slug":"features-tips-shortcuts","text":"t w switches between the standard reading column and Wide mode. The page keeps the same width while you edit, fold blocks, or open reference sections.","title":"Features/Tips & shortcuts"},{"anchor":"b33","slug":"features-tips-shortcuts","text":"Wide mode fills the available pane by default. To tune either layout on this device, open Settings → Appearance → Advanced: set the standard page width in pixels, or give Wide mode a custom maximum.","title":"Features/Tips & shortcuts"},{"anchor":"b34","slug":"features-tips-shortcuts","text":"A few more worth knowing","title":"Features/Tips & shortcuts"},{"anchor":"b35","slug":"features-tips-shortcuts","text":"In Settings → Keyboard Shortcuts, use the settings search field to filter commands by name, command ID, or current binding before recording a replacement.","title":"Features/Tips & shortcuts"},{"anchor":"b36","slug":"features-tips-shortcuts","text":"Use the … beside an ordinary page title for its complete actions menu: open the source file, copy/export, inspect properties, rename, carry tasks, or delete. It is the same menu as right-click and works from the keyboard and touch.","title":"Features/Tips & shortcuts"},{"anchor":"b37","slug":"features-tips-shortcuts","text":"Carry unfinished tasks forward into today (from the command palette) — the last 7 / 30 / 365 days, optionally with their context.","title":"Features/Tips & shortcuts"},{"anchor":"b38","slug":"features-tips-shortcuts","text":"Select several task bullets and press Ctrl/Cmd+Enter to advance each one through your workflow in a single Undo step. The selection toolbar can also wrap selected text as a page link or inline code.","title":"Features/Tips & shortcuts"},{"anchor":"b39","slug":"features-tips-shortcuts","text":"Namespaces: name a page Project/Roadmap and it nests under Project in the sidebar. This page lives under Features.","title":"Features/Tips & shortcuts"},{"anchor":"b40","slug":"features-tips-shortcuts","text":"Page icons: add a property like icon:: 📚 at the very top of a page — that's where the ⌨️ on this one comes from.","title":"Features/Tips & shortcuts"},{"anchor":"b41","slug":"features-tips-shortcuts","text":"Interface zoom with Ctrl + / - / 0, and PDFs, images, and audio all have their own controls.","title":"Features/Tips & shortcuts"},{"anchor":"b0","slug":"project-roadmap","text":"Project / Roadmap","title":"Project/Roadmap"},{"anchor":"b1","slug":"project-roadmap","text":"This page lives in the Project namespace, and it doubles as the target for the reference and the embed over on Welcome to Tine.","title":"Project/Roadmap"},{"anchor":"7a1c0f5e-0000-4000-8000-000000000001","slug":"project-roadmap","text":"Tine's saves are format-preserving, so you can always switch back to Logseq — nothing here is one-way.","title":"Project/Roadmap"},{"anchor":"b2","slug":"project-roadmap","text":"See the little count badge on the bullet above? That's how many blocks reference it — click the badge to see them.","title":"Project/Roadmap"},{"anchor":"b3","slug":"project-roadmap","text":"A few example tasks","title":"Project/Roadmap"},{"anchor":"b4","slug":"project-roadmap","text":"Write my first real note in Tine","title":"Project/Roadmap"},{"anchor":"b5","slug":"project-roadmap","text":"Set up the quick-capture hotkey — see Features/Quick capture","title":"Project/Roadmap"},{"anchor":"b6","slug":"project-roadmap","text":"Open my own Logseq graph and look around","title":"Project/Roadmap"},{"anchor":"b0","slug":"reference-files-external-edits-and-backups","text":"Files, external edits, and backups","title":"Reference/Files, external edits, and backups"},{"anchor":"b1","slug":"reference-files-external-edits-and-backups","text":"Your graph content stays in ordinary files shared with Logseq. Tine also keeps device settings and launch snapshots outside the graph. This page maps what is written where, and the safety nets around it.","title":"Reference/Files, external edits, and backups"},{"anchor":"b2","slug":"reference-files-external-edits-and-backups","text":"What lands on disk","title":"Reference/Files, external edits, and backups"},{"anchor":"b3","slug":"reference-files-external-edits-and-backups","text":"Pages and journals — one Markdown or Org file per page. Existing files may live at the graph root or in nested folders; Tine saves each one back to its exact path. New files use the configured pages/ and journals/ folders.","title":"Reference/Files, external edits, and backups"},{"anchor":"b4","slug":"reference-files-external-edits-and-backups","text":"Assets — pasted and uploaded files in assets/. Deleting a block never deletes its media.","title":"Reference/Files, external edits, and backups"},{"anchor":"b5","slug":"reference-files-external-edits-and-backups","text":"Graph configuration — logseq/config.edn, shared with Logseq: journal date formats, macros, and UI choices such as :ui/show-brackets? live there.","title":"Reference/Files, external edits, and backups"},{"anchor":"b6","slug":"reference-files-external-edits-and-backups","text":"Tine's view config — harmless tine.* block properties on the view-owning block (see Features/Sheets). Everything else stays ordinary graph text.","title":"Reference/Files, external edits, and backups"},{"anchor":"b7","slug":"reference-files-external-edits-and-backups","text":"Saving","title":"Reference/Files, external edits, and backups"},{"anchor":"b8","slug":"reference-files-external-edits-and-backups","text":"You never press Save: edits are written automatically to the same file the page came from, about half a second after a pause, and byte-identical rewrites are skipped.","title":"Reference/Files, external edits, and backups"},{"anchor":"b9","slug":"reference-files-external-edits-and-backups","text":"Writes are atomic and format-preserving — tabs vs spaces, comments, and compact EDN survive round-trips.","title":"Reference/Files, external edits, and backups"},{"anchor":"b10","slug":"reference-files-external-edits-and-backups","text":"A page rename is transactional: the file move and every [[reference]] / #tag rewrite commit together, re-checked just before writing, or roll back.","title":"Reference/Files, external edits, and backups"},{"anchor":"b11","slug":"reference-files-external-edits-and-backups","text":"An Org file is rewritten only when Tine can reproduce it byte-for-byte; one it cannot round-trip opens read-only so the graph cannot be corrupted.","title":"Reference/Files, external edits, and backups"},{"anchor":"b12","slug":"reference-files-external-edits-and-backups","text":"External edits","title":"Reference/Files, external edits, and backups"},{"anchor":"b13","slug":"reference-files-external-edits-and-backups","text":"Tine notices changes made outside it — Logseq, Syncthing, or another editor. Settings (t s) → Files → Watch for external edits: Live (inotify) (default, no idle wakeups) or Poll (3s) for filesystems where the OS watcher misses edits (some network mounts). Saved per device.","title":"Reference/Files, external edits, and backups"},{"anchor":"b14","slug":"reference-files-external-edits-and-backups","text":"A page you are not editing updates in place automatically. A page with unsaved edits is never overwritten: Tine shows a banner and skips that page in future saves until you choose Use disk version (re-read the file) or Keep mine (overwrite) (write your version).","title":"Reference/Files, external edits, and backups"},{"anchor":"b15","slug":"reference-files-external-edits-and-backups","text":"Prefer to approve even clean external updates yourself? Turn on Settings → Backups & recovery → Always ask before applying an external change. Tine then holds the silent case and offers Reload from disk / Keep mine; changes that already conflict or arrive mid-edit keep their existing safer handling.","title":"Reference/Files, external edits, and backups"},{"anchor":"b16","slug":"reference-files-external-edits-and-backups","text":"Returning to Tine asks the watcher for a fresh pass, covering network mounts, suspended apps, and sync tools that delivered no live filesystem event. A large git checkout, fossil update, branch switch, or sync burst is grouped into one external revision and summarized once instead of interrupting once per page.","title":"Reference/Files, external edits, and backups"},{"anchor":"b17","slug":"reference-files-external-edits-and-backups","text":"logseq/config.edn is live too. A change made in Logseq, a text editor, or delivered by a sync provider updates favorites, shortcuts, macros, the home page, journal formats, hidden properties, and other shared settings during the session; reopening the graph is not required. Tine reloads only when the file's bytes actually changed.","title":"Reference/Files, external edits, and backups"},{"anchor":"b18","slug":"reference-files-external-edits-and-backups","text":"Running two Tine windows on the same graph — or on a graph nested inside an open one — is refused, so that conflict cannot happen locally. For file sync between devices, run one app at a time on the graph where you can, and let conflict copies (below) catch the rest.","title":"Reference/Files, external edits, and backups"},{"anchor":"b19","slug":"reference-files-external-edits-and-backups","text":"Snapshots — automatic backups","title":"Reference/Files, external edits, and backups"},{"anchor":"b20","slug":"reference-files-external-edits-and-backups","text":"Each time Tine opens your graph it snapshots eligible Markdown/Org files across the graph, plus logseq/config.edn and asset .edn sidecars, to a local folder outside the graph. Syncthing never syncs it. Binary assets are not copied.","title":"Reference/Files, external edits, and backups"},{"anchor":"b21","slug":"reference-files-external-edits-and-backups","text":"Settings → Backups & recovery → Snapshots to keep (default 12) controls how many survive; the oldest beyond the count are pruned.","title":"Reference/Files, external edits, and backups"},{"anchor":"b22","slug":"reference-files-external-edits-and-backups","text":"1. Pick a snapshot and choose Restore, then confirm.","title":"Reference/Files, external edits, and backups"},{"anchor":"b23","slug":"reference-files-external-edits-and-backups","text":"2. What you should see: Tine snapshots your current state first, restores backed-up graph text to its original paths, restores config and sidecars, and reloads the graph — a mistaken restore is itself reversible.","title":"Reference/Files, external edits, and backups"},{"anchor":"b24","slug":"reference-files-external-edits-and-backups","text":"Trash","title":"Reference/Files, external edits, and backups"},{"anchor":"b25","slug":"reference-files-external-edits-and-backups","text":"Deleting a page or journal moves the file to logseq/.tine-trash/pages/ or logseq/.tine-trash/journals/, not permanent deletion. Its name gains a timestamp followed by __.","title":"Reference/Files, external edits, and backups"},{"anchor":"b26","slug":"reference-files-external-edits-and-backups","text":"Duplicate journal files you trash, discarded sync-conflict copies, and unused media from an orphan scan land there too.","title":"Reference/Files, external edits, and backups"},{"anchor":"b27","slug":"reference-files-external-edits-and-backups","text":"To restore something, open the matching typed folder, remove the timestamp and __ from its name, then move it into pages/, journals/, or assets/ with your file manager. Tine picks it up like any external change.","title":"Reference/Files, external edits, and backups"},{"anchor":"b28","slug":"reference-files-external-edits-and-backups","text":"Settings → Files → Orphan assets and trash can find media no block links to (a deleted block keeps its files, so unused media accumulates) and trash it, and Empty asset trash deletes asset trash permanently — page, journal, and conflict recovery files are always kept.","title":"Reference/Files, external edits, and backups"},{"anchor":"b29","slug":"reference-files-external-edits-and-backups","text":"Sync tools and conflict copies","title":"Reference/Files, external edits, and backups"},{"anchor":"b30","slug":"reference-files-external-edits-and-backups","text":"Keep Syncthing or Dropbox on your graph — Tine is built to coexist with them. Two files that resolve to the same journal day are kept, not dropped: Settings → Backups & recovery → Duplicate journal days offers Open, Merge, Rename, or Trash per file.","title":"Reference/Files, external edits, and backups"},{"anchor":"b31","slug":"reference-files-external-edits-and-backups","text":"To prove that two devices really have the same source tree, open Settings → Diagnostics → Verify synchronized graph on each one. Choose Create graph verification report, copy the report from one device to the other, paste it under Report from the other device, then choose Compare reports. Tine hashes the actual Markdown and Org bytes across nested and nonstandard layouts; reports contain paths and page names but no file contents, and nothing is uploaded automatically.","title":"Reference/Files, external edits, and backups"},{"anchor":"b32","slug":"reference-files-external-edits-and-backups","text":"A *.sync-conflict-* (or (conflicted copy)) file never appears as a page. Files carrying unresolved git or Fossil merge markers are also quarantined from ordinary saves rather than rewritten.","title":"Reference/Files, external edits, and backups"},{"anchor":"b33","slug":"reference-files-external-edits-and-backups","text":"Both kinds appear in one N conflicts queue at the bottom of the sidebar. Open a conflicted page to compare the complete versions block by block; each row previews its first differing line and can expand to the full text. A duplicate journal day opens the same review directly on that day, with per-file Open / Rename / Trash actions. Choose keep-mine, keep-theirs, keep-both, or a suggested Merged version when both sides edited separate parts of one block, then Apply resolution. A pinned notice keeps the review reachable while you scroll. Nothing is auto-merged or auto-deleted, and leaving with choices unfinished never blocks you.","title":"Reference/Files, external edits, and backups"},{"anchor":"b34","slug":"reference-files-external-edits-and-backups","text":"Settings → Backups & recovery keeps the inventory: Review in page… opens a conflict and Discard copy moves a provider conflict copy to the trash.","title":"Reference/Files, external edits, and backups"},{"anchor":"b35","slug":"reference-files-external-edits-and-backups","text":"Tine's own operation-backed sync is a separate, opt-in, known-buggy mode — see Features/Managed sync. Ordinary provider sync needs no setup at all.","title":"Reference/Files, external edits, and backups"},{"anchor":"b36","slug":"reference-files-external-edits-and-backups","text":"Journal files named by title","title":"Reference/Files, external edits, and backups"},{"anchor":"b37","slug":"reference-files-external-edits-and-backups","text":"Tine does not silently rename journal files when a graph opens. If an otherwise valid journal uses its display title as its filename (for example Jun 18th, 2026.md), the day may look empty because the filename cannot be matched to its date.","title":"Reference/Files, external edits, and backups"},{"anchor":"b38","slug":"reference-files-external-edits-and-backups","text":"Settings → Backups & recovery → Journal files named by title lists these files. Review the list and choose the explicit rename action; Tine takes a snapshot first and never overwrites an occupied destination.","title":"Reference/Files, external edits, and backups"},{"anchor":"b39","slug":"reference-files-external-edits-and-backups","text":"Export","title":"Reference/Files, external edits, and backups"},{"anchor":"b40","slug":"reference-files-external-edits-and-backups","text":"Settings → Graph → Export graph to HTML publishes your public:: true pages as a standalone site with fuzzy block search.","title":"Reference/Files, external edits, and backups"},{"anchor":"b41","slug":"reference-files-external-edits-and-backups","text":"Right-click a page title → Export to PDF… prints one page on a light background with images inlined.","title":"Reference/Files, external edits, and backups"},{"anchor":"b42","slug":"reference-files-external-edits-and-backups","text":"Copy/export as on a block or page names its two content choices explicitly: Plain text (cleaned, as displayed) or Markdown source (preserves syntax). The Text / OPML / HTML destinations and cleanup/depth controls then apply to that choice.","title":"Reference/Files, external edits, and backups"},{"anchor":"b0","slug":"reference-journals-tasks-and-scheduling","text":"Journals, tasks, and scheduling","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b1","slug":"reference-journals-tasks-and-scheduling","text":"Everything dated lives here: one journal page per day, tasks as plain-text markers at the start of a block, [#A]–[#C] priorities, and SCHEDULED:/DEADLINE: planning lines with calendar pickers. This page maps the shipped behavior; Workflows/Capture and plan your day walks through using it, and Feature showcase shows each construct rendered.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b2","slug":"reference-journals-tasks-and-scheduling","text":"Journals","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b3","slug":"reference-journals-tasks-and-scheduling","text":"The Journals entry in the sidebar opens a multi-day feed — one continuous, editable list, newest day first. Today's journal page is created lazily on first edit: the feed shows the day, but no file exists until you type.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b4","slug":"reference-journals-tasks-and-scheduling","text":"Each journal title parses as a date in the graph's journal formats, so a [[date]]-looking reference routes to that journal page rather than opening an empty named page.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b5","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals → Journal date format controls the display titles and how new [[date]] titles are written (saved to :journal/page-title-format, traveling with the graph). It is display-only: journal file names are untouched and existing journals keep working; for files, duplicate days, and the on-disk layout in general, see Reference/Files, external edits, and backups.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b6","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals → New-journal template inserts a template into each new day (:default-templates {:journals …} in config.edn); “(none)” means blank days, the default. Make a template from a block's right-click menu.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b7","slug":"reference-journals-tasks-and-scheduling","text":"Task markers","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b8","slug":"reference-journals-tasks-and-scheduling","text":"The marker set is TODO, DOING, NOW, LATER, WAITING, WAIT, STARTED, IN-PROGRESS, DONE, CANCELED, CANCELLED — stored as the plain first word of the block's first line, like Logseq.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b9","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals → Task workflow chooses between two cycling lanes, TODO / DOING and NOW / LATER (:preferred-workflow, traveling with the graph); NOW / LATER is the default.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b10","slug":"reference-journals-tasks-and-scheduling","text":"Click the marker chip for Logseq's two-state progress toggle: TODO ↔ DOING or LATER ↔ NOW. Click the checkbox to finish as DONE (and again to reopen). Ctrl+Enter (Cmd on Mac) uses the full keyboard cycle TODO → DOING → DONE → none, or LATER → NOW → DONE → none, applied to every selected task when several blocks are selected.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b11","slug":"reference-journals-tasks-and-scheduling","text":"Every task also shows a checkbox in front of it: click to mark DONE, click again to reopen to the workflow's open marker (TODO or LATER). DONE shows a checked box; CANCELED/CANCELLED show none. Checkboxes appear read-only inside query results, linked references, and embeds.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b12","slug":"reference-journals-tasks-and-scheduling","text":"Queries filter on markers with a task clause, e.g. (task TODO DOING) in {{query }} or in the visual query builder.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b13","slug":"reference-journals-tasks-and-scheduling","text":"Priorities","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b14","slug":"reference-journals-tasks-and-scheduling","text":"[#A], [#B], [#C] sit directly after the task marker; a block without a task marker can carry one too. Type slash, choose Priority A (or B, C), and the chip updates in place.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b15","slug":"reference-journals-tasks-and-scheduling","text":"Priorities are queryable and sortable in the visual builder too, and they render like any other header facet — the Feature showcase has them all.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b16","slug":"reference-journals-tasks-and-scheduling","text":"Scheduled and deadline dates","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b17","slug":"reference-journals-tasks-and-scheduling","text":"A block's plan is a SCHEDULED: and/or DEADLINE: line with an Org-style timestamp <2026-07-07 Tue>, optionally with a clock time <2026-07-07 Tue 14:30>. Convention: use SCHEDULED for the day you intend to work on something, DEADLINE for the day it must be done.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b18","slug":"reference-journals-tasks-and-scheduling","text":"While editing, type / and choose Scheduled or Deadline: a calendar popup picks the day (its first weekday follows Settings → Journals → First day of week), and Add time attaches HH:mm. The block then gains a calendar date chip — click it to change the date again; re-picking keeps an existing time (and any repeater).","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b19","slug":"reference-journals-tasks-and-scheduling","text":"You may also type a planning line anywhere in the block: on leaving the editor it moves to its canonical spot — right after the first line, before any properties, SCHEDULED before DEADLINE — like Logseq. A SCHEDULED: inside inline code or a code fence stays literal content and is never moved.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b20","slug":"reference-journals-tasks-and-scheduling","text":"The same chips and pickers appear wherever the block does; a sheet's Scheduled/Deadline cells go through the same path (see Features/Sheets).","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b21","slug":"reference-journals-tasks-and-scheduling","text":"Agenda","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b22","slug":"reference-journals-tasks-and-scheduling","text":"Today's journal ends with a Scheduled &amp; Deadline list of open items whose date falls inside the Agenda window — by default 7 days back and 7 ahead, adjustable and persisted in Settings → Journals → Agenda window. It disappears entirely when nothing matches.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b23","slug":"reference-journals-tasks-and-scheduling","text":"Keyed off the scheduled/deadline date itself, not the page's journal day: an unfinished item on an old page still shows while its date is in range. The underlying stored query is (and (or (between scheduled -7d +7d) (between deadline -7d +7d)) (not (task DONE CANCELED CANCELLED))).","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b24","slug":"reference-journals-tasks-and-scheduling","text":"Finished tasks (DONE, CANCELED, CANCELLED) never appear, matching Logseq.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b25","slug":"reference-journals-tasks-and-scheduling","text":"Time tracking and the logbook","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b26","slug":"reference-journals-tasks-and-scheduling","text":"With Settings → Journals → Time tracking on (the default), moving into DOING / NOW records a clock-in and moving back to TODO / LATER or into DONE records a clock-out, as OG-compatible :LOGBOOK: CLOCK: rows (seconds on by default via :logbook/settings). Saved to :feature/enable-timetracking?.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b27","slug":"reference-journals-tasks-and-scheduling","text":"Blocks with clock rows show a small elapsed-time badge with a Type / Start / End / Span tooltip; the :LOGBOOK: drawer itself stays hidden by default, like Logseq.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b28","slug":"reference-journals-tasks-and-scheduling","text":"Toggled off, markers change without writing log rows.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b29","slug":"reference-journals-tasks-and-scheduling","text":"Repeating tasks","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b30","slug":"reference-journals-tasks-and-scheduling","text":"Put a repeater inside the timestamp, e.g. <2026-07-07 Tue +1w>; the units are d, w, m, y for days, weeks, months, years.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b31","slug":"reference-journals-tasks-and-scheduling","text":"Marking a repeating task done does not close it: the date advances to the next occurrence and the marker resets to the workflow's open state (TODO, or LATER under NOW / LATER). This works from the checkbox, the marker chip, and Ctrl+Enter.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b32","slug":"reference-journals-tasks-and-scheduling","text":"+1w advances from the stored date; .+1w counts from the day you complete it; ++1w skips missed occurrences, landing past today. The repeater survives date re-picks in the calendar.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b33","slug":"reference-journals-tasks-and-scheduling","text":"Settings quick map","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b34","slug":"reference-journals-tasks-and-scheduling","text":"Settings → Journals collects every control above: Journal date format, First day of week, Task workflow, Time tracking, New-journal template, and Agenda window, plus the carry-over controls — for those in use, see Workflows/Capture and plan your day.","title":"Reference/Journals, tasks, and scheduling"},{"anchor":"b0","slug":"reference-pages-links-references-and-search","text":"Pages, links, references, and search","title":"Reference/Pages, links, references, and search"},{"anchor":"b1","slug":"reference-pages-links-references-and-search","text":"The precise rules behind the moving parts: pages and aliases, links and tags, block references and embeds, the two reference panels on every page, and every search surface from the switcher to the saved-search page. Workflows/Find and revisit walks through using them in order; Feature showcase shows each construct rendered.","title":"Reference/Pages, links, references, and search"},{"anchor":"b2","slug":"reference-pages-links-references-and-search","text":"Pages and namespaces","title":"Reference/Pages, links, references, and search"},{"anchor":"b3","slug":"reference-pages-links-references-and-search","text":"A page is any name you link to. Type [[ while editing and completion offers existing pages; whether Enter prefers the strongest existing match or exactly what you typed is Settings → Editor → Advanced → Link autocomplete default, and an exact existing name always wins.","title":"Reference/Pages, links, references, and search"},{"anchor":"b4","slug":"reference-pages-links-references-and-search","text":"A link to a page that does not exist yet renders muted with a dotted underline. It isn't broken — opening it creates the page. (Logseq draws missing and live links identically; Tine marks the difference on purpose.)","title":"Reference/Pages, links, references, and search"},{"anchor":"b5","slug":"reference-pages-links-references-and-search","text":"A name with slashes, like Project/Roadmap, is a namespace: it nests under Project in the sidebar's collapsible namespace tree, and a namespaced page gains an automatic Hierarchy section with the breadcrumb paths of its descendant pages.","title":"Reference/Pages, links, references, and search"},{"anchor":"b6","slug":"reference-pages-links-references-and-search","text":"Journals are pages too — one per day, reachable from Journals in the sidebar. Their formats, templates, tasks, and agenda are mapped in Reference/Journals, tasks, and scheduling.","title":"Reference/Pages, links, references, and search"},{"anchor":"b7","slug":"reference-pages-links-references-and-search","text":"Links and tags","title":"Reference/Pages, links, references, and search"},{"anchor":"b8","slug":"reference-pages-links-references-and-search","text":"[[Page]] links and #tag tags run on the same machinery: a tag links and collects references like any page, and a tag with no page of its own is perfectly normal. A page's tags:: property values render as navigable links too; quoted property values stay literal text.","title":"Reference/Pages, links, references, and search"},{"anchor":"b9","slug":"reference-pages-links-references-and-search","text":"A labelled page link such as read the welcome shows your words while opening the page. External [label](https://…) links are ordinary Markdown, bare URLs and emails autolink, and Mod+L wraps the selection as an external link.","title":"Reference/Pages, links, references, and search"},{"anchor":"b10","slug":"reference-pages-links-references-and-search","text":"Click a link to follow it. While editing, Ctrl+O opens the link at the caret and Ctrl+Shift+O opens it in the right sidebar — matching Logseq's shortcuts, no mouse needed.","title":"Reference/Pages, links, references, and search"},{"anchor":"b11","slug":"reference-pages-links-references-and-search","text":"Aliases","title":"Reference/Pages, links, references, and search"},{"anchor":"b12","slug":"reference-pages-links-references-and-search","text":"Put alias:: Another name, Third name among the page properties at the top of a page — as Feature showcase does with alias:: Kitchen sink (features) — and links under those names land on the same page.","title":"Reference/Pages, links, references, and search"},{"anchor":"b13","slug":"reference-pages-links-references-and-search","text":"The page then shows read-only aka chips for every name it answers to (\"Also known as — other names that link here\"), and the raw alias:: property stays out of the under-title property list.","title":"Reference/Pages, links, references, and search"},{"anchor":"b14","slug":"reference-pages-links-references-and-search","text":"Block references and embeds","title":"Reference/Pages, links, references, and search"},{"anchor":"b15","slug":"reference-pages-links-references-and-search","text":"Type (( while editing: the popup full-text-searches blocks, and choosing one inserts a durable ((reference)) — Tine first writes a stable id:: on the source block, so the reference survives renames, reloads, and restarts.","title":"Reference/Pages, links, references, and search"},{"anchor":"b16","slug":"reference-pages-links-references-and-search","text":"The reference renders as a link-styled copy of the source text — not a grey chip — and stays in sync: edit the source and every reference updates. A per-block reference-count badge reveals the referencing blocks, grouped by page with ancestor breadcrumbs.","title":"Reference/Pages, links, references, and search"},{"anchor":"b17","slug":"reference-pages-links-references-and-search","text":"Right-click an inline reference for open in sidebar, go to block, copy ref, and copy embed; Mod+C with nothing selected copies a reference to the block you're editing.","title":"Reference/Pages, links, references, and search"},{"anchor":"b18","slug":"reference-pages-links-references-and-search","text":"Copying a block to the clipboard strips its id::, like Logseq, so an internal id never leaks into a paste; the id stays in your file.","title":"Reference/Pages, links, references, and search"},{"anchor":"b19","slug":"reference-pages-links-references-and-search","text":"{{embed [[Page]]}} and {{embed ((id))}} inline a whole page or a block with its context. Embeds are live editing surfaces: edit inside an embed and the source changes, while folding inside an embed stays local to that embed.","title":"Reference/Pages, links, references, and search"},{"anchor":"b20","slug":"reference-pages-links-references-and-search","text":"The reference panels on every page","title":"Reference/Pages, links, references, and search"},{"anchor":"b21","slug":"reference-pages-links-references-and-search","text":"Linked References sits at the bottom of the page (and of a page opened in the right sidebar): every block that links here — large panels group them by source page with bounded, highlighted excerpts. It's live — edit in place — and the chip filter narrows to blocks that also mention a second page, cycling include → exclude → off like Logseq's filter.","title":"Reference/Pages, links, references, and search"},{"anchor":"b22","slug":"reference-pages-links-references-and-search","text":"Type into its search box to narrow both the references and the available page/tag chips. A chip you already selected remains visible at count zero when the text removes its last match, so the filter can always be undone. While the descendant index is still loading, Tine says it is indexing and deliberately leaves the list unfiltered instead of displaying a false filtered count.","title":"Reference/Pages, links, references, and search"},{"anchor":"b23","slug":"reference-pages-links-references-and-search","text":"Unlinked References, folded by default: plain-text mentions of the page title that were never linked — the fastest way to find where a name was written without brackets.","title":"Reference/Pages, links, references, and search"},{"anchor":"b24","slug":"reference-pages-links-references-and-search","text":"Both panels have their own Copy / export action. The currently visible entries start selected; uncheck any you do not need, then export the selected blocks grouped by source page as Text, OPML, or HTML. Linked References exports its filtered set, and ordinary page export remains separate.","title":"Reference/Pages, links, references, and search"},{"anchor":"b25","slug":"reference-pages-links-references-and-search","text":"Deep matches start folded behind an ancestor breadcrumb, in a view-local copy that never changes the source block's own collapse state; hover previews show surrounding context without leaving the page.","title":"Reference/Pages, links, references, and search"},{"anchor":"b26","slug":"reference-pages-links-references-and-search","text":"Finding things","title":"Reference/Pages, links, references, and search"},{"anchor":"b27","slug":"reference-pages-links-references-and-search","text":"Ctrl+K, the quick switcher, searches page titles plus the visible text of blocks — hidden properties and ids never produce phantom hits. Shift+Enter opens the highlighted result in the right sidebar; middle-click opens a background tab.","title":"Reference/Pages, links, references, and search"},{"anchor":"b28","slug":"reference-pages-links-references-and-search","text":"Ctrl+Shift+K searches only the open page's blocks, including folded descendants. Mod+F opens the in-page find bar with next/previous and an n-of-total count; folded branches are expanded before the match is highlighted.","title":"Reference/Pages, links, references, and search"},{"anchor":"b29","slug":"reference-pages-links-references-and-search","text":"The five Search syntax forms, listed in the switcher footer: foo bar (both terms), foo OR bar (either), foo -draft (exclude), \"exact phrase\", and /[A-Z]{3}/ (case-sensitive regular expression).","title":"Reference/Pages, links, references, and search"},{"anchor":"b30","slug":"reference-pages-links-references-and-search","text":"Title matches rank exact, then prefix, then substring, then fuzzy. After you deliberately open the same result more than once for a query, it may break ties among equally strong matches; that history stays on this device and in this graph, and Settings → Editor → Learn Ctrl+K choices disables or resets it.","title":"Reference/Pages, links, references, and search"},{"anchor":"b31","slug":"reference-pages-links-references-and-search","text":"Composed and decomposed Unicode spellings of the same text share matches (so both forms of an accented name are found); accent folding is deliberately not added, so cafe does not match café.","title":"Reference/Pages, links, references, and search"},{"anchor":"b32","slug":"reference-pages-links-references-and-search","text":"The in-app Guide itself stays out of search, page lists, and backlinks.","title":"Reference/Pages, links, references, and search"},{"anchor":"b33","slug":"reference-pages-links-references-and-search","text":"Search tabs and saved searches","title":"Reference/Pages, links, references, and search"},{"anchor":"b34","slug":"reference-pages-links-references-and-search","text":"Open search tab in the switcher footer turns the current search into a graph-scoped search tab with its own search box. The tab survives restarts and writes nothing to your graph until you name it.","title":"Reference/Pages, links, references, and search"},{"anchor":"b35","slug":"reference-pages-links-references-and-search","text":"Search / List / Table / Board are presentations of one result membership: switching the view never changes which blocks matched. Filters / Advanced narrows by friendly fields and date ranges; Edit as visual query opens the chip-by-chip builder; Explain query shows what Tine understood. Choosing blocks and choosing a presentation are separate steps — see Workflows/Structure repeated information for that split in action.","title":"Reference/Pages, links, references, and search"},{"anchor":"b36","slug":"reference-pages-links-references-and-search","text":"Naming a search tab — typing into \"Name this search to save it as a page\" and pressing Save page — creates one ordinary page whose only block is a {{query}} (plus a tine.view:: line unless you chose the plain List view). From then on it behaves like any page: linkable, searchable, always fresh. A page that already exists with the chosen name is never overwritten — you pick another name.","title":"Reference/Pages, links, references, and search"},{"anchor":"b37","slug":"reference-pages-links-references-and-search","text":"A {{query [[Page]]}} block uses Logseq's path-refs rule: a block matches when it mentions the page, when a bullet it lives under does, or when it sits on that page — so the page's own outline always appears. The backlinks-only answer to the same question is the page's Linked References panel.","title":"Reference/Pages, links, references, and search"},{"anchor":"b38","slug":"reference-pages-links-references-and-search","text":"Related","title":"Reference/Pages, links, references, and search"},{"anchor":"b39","slug":"reference-pages-links-references-and-search","text":"Workflows/Find and revisit — the task-first path over these pieces.","title":"Reference/Pages, links, references, and search"},{"anchor":"b40","slug":"reference-pages-links-references-and-search","text":"Features/Tips & shortcuts — the wider shortcut map: tabs, sidebars, focus mode.","title":"Reference/Pages, links, references, and search"},{"anchor":"b41","slug":"reference-pages-links-references-and-search","text":"Feature showcase — every construct above, rendered live.","title":"Reference/Pages, links, references, and search"},{"anchor":"b0","slug":"reference-platforms-and-mobile","text":"Platforms and mobile","title":"Reference/Platforms and mobile"},{"anchor":"b1","slug":"reference-platforms-and-mobile","text":"\"Does this work on my phone?\" hides two different questions: what changes because a window is narrow, and what changes because Tine is running as the Android app instead of a desktop one. This page keeps them apart and maps what current public releases ship on each side.","title":"Reference/Platforms and mobile"},{"anchor":"b2","slug":"reference-platforms-and-mobile","text":"Question 1 — is the window narrow?","title":"Reference/Platforms and mobile"},{"anchor":"b3","slug":"reference-platforms-and-mobile","text":"Below a 640 px window width — on any device, including a desktop window you shrank yourself — the left and right sidebars stop squeezing the page and become drawers over it. Dismiss one by tapping the shaded outside edge, using its close control, pressing Esc, or pressing Android Back.","title":"Reference/Platforms and mobile"},{"anchor":"b4","slug":"reference-platforms-and-mobile","text":"At 640 px and wider — including tablets — both sidebars are persistent panes that can stay open together and keep their resize controls.","title":"Reference/Platforms and mobile"},{"anchor":"b5","slug":"reference-platforms-and-mobile","text":"The boundary is width, nothing else: it follows the window, not the device, so the same desktop shows both faces as you resize it.","title":"Reference/Platforms and mobile"},{"anchor":"b6","slug":"reference-platforms-and-mobile","text":"Question 2 — which app is running?","title":"Reference/Platforms and mobile"},{"anchor":"b7","slug":"reference-platforms-and-mobile","text":"Some behavior keys off Tine detecting a native mobile platform, whatever the window width. The Android app hides the tab strip and disables split panes, so one page keeps the phone screen; workspaces carry the simple one-pane layout there.","title":"Reference/Platforms and mobile"},{"anchor":"b8","slug":"reference-platforms-and-mobile","text":"The desktop apps (Linux, macOS, Windows) keep the full window model — tabs, pinned tabs, split panes, saved workspaces, and multiple windows — toured in Workflows/Keep context visible.","title":"Reference/Platforms and mobile"},{"anchor":"b9","slug":"reference-platforms-and-mobile","text":"In both cases your graph is the same ordinary Markdown/Org files, so these are interface and surface differences, never different content formats.","title":"Reference/Platforms and mobile"},{"anchor":"b10","slug":"reference-platforms-and-mobile","text":"On Android","title":"Reference/Platforms and mobile"},{"anchor":"b11","slug":"reference-platforms-and-mobile","text":"Your graph is a real folder. On first run you grant \"All files access\" and pick the graph folder (a Syncthing folder works), and Tine reads and writes that folder directly — coexisting with the Logseq mobile app on one graph. The file watcher polls there by default, so external edits appear shortly after they land.","title":"Reference/Platforms and mobile"},{"anchor":"b12","slug":"reference-platforms-and-mobile","text":"An editing toolbar docks above the on-screen keyboard with the actions a keyboard lacks: Outdent / Indent, Move block up / down, Soft newline, TODO, Camera, Voice memo, Date picker, [[ ]] and (( )), the Slash menu, Undo/Redo, and a pinned hide-keyboard button.","title":"Reference/Platforms and mobile"},{"anchor":"b13","slug":"reference-platforms-and-mobile","text":"Camera and Voice memo capture a photo (or an existing image) or an .m4a recording straight into the graph's assets/ folder and insert the link at the caret — permission-prompted on first use.","title":"Reference/Platforms and mobile"},{"anchor":"b14","slug":"reference-platforms-and-mobile","text":"Hardware Back navigates within Tine — dismissing a drawer or dialog first and stepping back through page history, exiting to the system only at the root.","title":"Reference/Platforms and mobile"},{"anchor":"b15","slug":"reference-platforms-and-mobile","text":"PDFs use that same one-pane history. Open a PDF link in place, press Notes to visit its highlights page, and use Hardware Back to return first to the PDF and then to the source page. Desktop-style PDF tabs and companion splits stay disabled on Android.","title":"Reference/Platforms and mobile"},{"anchor":"b16","slug":"reference-platforms-and-mobile","text":"Plugins and themes follow the same lifecycle as desktop — browse, install (always disabled at first), review its capabilities, enable, settings, disable, uninstall — and a package that did not declare Android shows Unavailable on it. The hands-on path is Workflows/Extend Tine.","title":"Reference/Platforms and mobile"},{"anchor":"b17","slug":"reference-platforms-and-mobile","text":"The whole interface scales through Interface size (saved per device) and the native status/navigation icons follow your selected theme.","title":"Reference/Platforms and mobile"},{"anchor":"b18","slug":"reference-platforms-and-mobile","text":"What stays different on Android","title":"Reference/Platforms and mobile"},{"anchor":"b19","slug":"reference-platforms-and-mobile","text":"Global quick capture is desktop-only — the tine --capture desktop shortcut and its always-on-top capture window have no Android counterpart. Its setup lives on Features/Quick capture.","title":"Reference/Platforms and mobile"},{"anchor":"b20","slug":"reference-platforms-and-mobile","text":"One route at a time — pages and PDF readers share one history, with no tab strip, split panes, or second windows; the desktop multi-window model does not exist here.","title":"Reference/Platforms and mobile"},{"anchor":"b21","slug":"reference-platforms-and-mobile","text":"Context menus open from the bullet affordance rather than a right-click anywhere; long-press on text stays with the system, so text selection works natively.","title":"Reference/Platforms and mobile"},{"anchor":"b22","slug":"reference-platforms-and-mobile","text":"In the PDF reader, highlight recolor and remove work, but the highlight menu's Copy ref and Linked references entries appear only on desktop.","title":"Reference/Platforms and mobile"},{"anchor":"b23","slug":"reference-platforms-and-mobile","text":"Updates come from you. The in-app update checker and installer are off on mobile; take each new release-signed APK from the GitHub releases page and sideload it. Distribution today is a sideloaded, release-signed APK attached to each GitHub release; Play Store and F-Droid are planned, and the F-Droid build will omit the network plugin/theme catalogue while keeping local sideloading.","title":"Reference/Platforms and mobile"},{"anchor":"b24","slug":"reference-platforms-and-mobile","text":"On desktop (Linux, macOS, Windows)","title":"Reference/Platforms and mobile"},{"anchor":"b25","slug":"reference-platforms-and-mobile","text":"Everything the phone skips is here: tabs with pin, reorder, and reopen, split panes, saved workspaces, multiple windows, the modifier-click gestures, and global quick capture.","title":"Reference/Platforms and mobile"},{"anchor":"b26","slug":"reference-platforms-and-mobile","text":"In-app updates run on Windows and Linux — the app checks once per launch and Settings → About → Check for updates downloads, installs, and relaunches in place. On macOS the same notice opens the releases page instead, because today's unsigned app bundle cannot safely replace itself.","title":"Reference/Platforms and mobile"},{"anchor":"b27","slug":"reference-platforms-and-mobile","text":"Any folder on your disk can be a graph — choose it with the ordinary folder picker; there is no sandboxed document picker.","title":"Reference/Platforms and mobile"},{"anchor":"b28","slug":"reference-platforms-and-mobile","text":"Releases also include an experimental 32-bit Windows installer and portable ZIP for older Windows 10 tablets. It is a manual-download pilot, not offered by automatic updates; ordinary Windows users should keep using the x64 package.","title":"Reference/Platforms and mobile"},{"anchor":"b29","slug":"reference-platforms-and-mobile","text":"iOS today","title":"Reference/Platforms and mobile"},{"anchor":"b30","slug":"reference-platforms-and-mobile","text":"There is no public iOS app — public releases ship the desktop apps and the Android APK, and iOS is being scoped.","title":"Reference/Platforms and mobile"},{"anchor":"b31","slug":"reference-platforms-and-mobile","text":"Some iOS words already exist in the source so a future app is prepared for — the folder-picker handling and the plugin manifest's ios platform value — but that is checked-in scaffolding and developer vocabulary, not an installable app. A plugin declaring only ios has no host to run on today.","title":"Reference/Platforms and mobile"},{"anchor":"b32","slug":"reference-platforms-and-mobile","text":"Where next","title":"Reference/Platforms and mobile"},{"anchor":"b33","slug":"reference-platforms-and-mobile","text":"Workflows/Keep context visible for tabs, panes, sidebars and workspaces (desktop), Features/Quick capture for the desktop capture window, Workflows/Extend Tine for the per-platform plugin and theme lifecycle, and Features/PDF annotation for the full reader tour.","title":"Reference/Platforms and mobile"},{"anchor":"b0","slug":"reference-troubleshooting-and-recovery","text":"Troubleshooting and recovery","title":"Reference/Troubleshooting and recovery"},{"anchor":"b1","slug":"reference-troubleshooting-and-recovery","text":"Only recovery paths Tine actually ships, each as numbered actions with the outcome to expect. For where everything lives, see Reference/Files, external edits, and backups.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b2","slug":"reference-troubleshooting-and-recovery","text":"“Page changed on disk” banner","title":"Reference/Troubleshooting and recovery"},{"anchor":"b3","slug":"reference-troubleshooting-and-recovery","text":"Meaning: the file changed elsewhere (a sync tool or another editor) while you had unsaved edits. Nothing was written over — your unsaved text is still on screen.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b4","slug":"reference-troubleshooting-and-recovery","text":"1. If the disk version is the one you want, choose Use disk version — Tine re-reads the file. Copy your unsaved text somewhere first if you still need parts of it.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b5","slug":"reference-troubleshooting-and-recovery","text":"2. If your version is right, choose Keep mine (overwrite) — Tine writes yours over the file.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b6","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: the banner clears and the page saves normally again. Until you choose, that page is skipped by saving rather than silently clobbered.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b7","slug":"reference-troubleshooting-and-recovery","text":"Restore a deleted page or journal","title":"Reference/Troubleshooting and recovery"},{"anchor":"b8","slug":"reference-troubleshooting-and-recovery","text":"1. Open logseq/.tine-trash/pages/ or logseq/.tine-trash/journals/ inside your graph. Deleted files have a timestamp followed by __ before their original name.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b9","slug":"reference-troubleshooting-and-recovery","text":"2. Remove the timestamp and __, then move the file into the configured pages or journals folder. For a page that originally lived elsewhere, you may return it to that location instead.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b10","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: Tine notices the restored file like any external change, and the page reappears.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b11","slug":"reference-troubleshooting-and-recovery","text":"Review several deletions in Tine-managed storage","title":"Reference/Troubleshooting and recovery"},{"anchor":"b12","slug":"reference-troubleshooting-and-recovery","text":"1. Open the Deleted pages dock after the warning appears. Tier 2 starts at four deletions; Tier 3 covers at least 10% of the graph (rounded up), or 50 pages when that is lower, and pauses propagation for about five minutes. Smaller Tier 1 sweeps stay quiet.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b13","slug":"reference-troubleshooting-and-recovery","text":"2. Review every member page, then choose exactly one explicit action: Restore, Re-apply, or Keep deletion. Closing the warning or panel records no choice and does not dispose the sweep.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b14","slug":"reference-troubleshooting-and-recovery","text":"3. If Restore fails, read the recorded cause and choose Run Restore again. Tine resumes through its durable whole-sweep Restore; do not recreate pages one at a time while it is running.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b15","slug":"reference-troubleshooting-and-recovery","text":"4. What you should see: progress and completion update live, and the finished sweep remains visible with Restored, Deletion re-applied, or Deletion kept. This surface applies only to experimental managed storage; the single-file steps above remain the Direct files recovery path. See Features/Managed sync.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b16","slug":"reference-troubleshooting-and-recovery","text":"Restore an earlier state of the graph","title":"Reference/Troubleshooting and recovery"},{"anchor":"b17","slug":"reference-troubleshooting-and-recovery","text":"1. Open Settings (t s) → Backups & recovery and find the snapshot from before the damage. (Tine snapshots your Markdown/Org files on every launch; Snapshots to keep controls how many survive.)","title":"Reference/Troubleshooting and recovery"},{"anchor":"b18","slug":"reference-troubleshooting-and-recovery","text":"2. Choose Restore beside it and confirm.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b19","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: your current state is snapshotted first, backed-up graph text returns to its original paths, config and sidecars are restored, and the graph reloads — so even a mistaken restore can be undone by restoring the snapshot it just made.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b20","slug":"reference-troubleshooting-and-recovery","text":"Resolve a sync or version-control conflict","title":"Reference/Troubleshooting and recovery"},{"anchor":"b21","slug":"reference-troubleshooting-and-recovery","text":"1. Choose the N conflicts badge at the bottom of the sidebar, or open Settings → Backups & recovery and choose Review in page…. Tine uses the same queue for sync-provider conflict copies and files carrying unresolved git or Fossil merge markers.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b22","slug":"reference-troubleshooting-and-recovery","text":"2. On the page, compare the complete versions in the block-by-block review. Each row previews its first differing line and can expand to full text. Accept or change each suggestion: when both sides edited separate parts of one block, Tine may offer a combined Merged version; otherwise choose either side or keep both. Choose page properties separately when needed, then Apply resolution. The review's slim pinned notice keeps it reachable while you scroll without losing your choices.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b23","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: the chosen page is saved through the normal guarded path. A provider conflict copy moves to the trash; before a version-control page is written without conflict markers, its exact pre-resolution file is kept in recoverable trash. If a conflict copy's original page no longer exists, discard the copy in Settings or restore the page in Logseq first.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b24","slug":"reference-troubleshooting-and-recovery","text":"Reconcile a duplicate journal day","title":"Reference/Troubleshooting and recovery"},{"anchor":"b25","slug":"reference-troubleshooting-and-recovery","text":"1. Open the affected journal day from the N conflicts queue. Tine shows both files in the same block-by-block review used for provider conflicts; each file also has Open, Rename, and Trash actions. The same inventory remains in Settings → Backups & recovery → Duplicate journal days.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b26","slug":"reference-troubleshooting-and-recovery","text":"2. Choose which version of each differing block to keep (or keep both), then Apply resolution. The old Settings Merge action is the same keep-both outcome.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b27","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: the chosen content saved as the day and the other file moved to recoverable trash. Tine kept both source files until you decided rather than dropping one.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b28","slug":"reference-troubleshooting-and-recovery","text":"Tine will not start","title":"Reference/Troubleshooting and recovery"},{"anchor":"b29","slug":"reference-troubleshooting-and-recovery","text":"1. Run it with debug logging: TINE_DEBUG=1 tine (or tine --debug; the AppImage the same way), reproduce the problem, then quit.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b30","slug":"reference-troubleshooting-and-recovery","text":"2. Tine prints the log path on startup. By default it is tine-debug.log in your platform's temporary folder; TINE_DEBUG_LOG=/path overrides it.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b31","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: a timestamped trace covering the environment, startup milestones, and any panic with a backtrace. It records no note content — send that file with your report.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b32","slug":"reference-troubleshooting-and-recovery","text":"4. On Linux, if the window never appears at all, run TINE_GPU=0 tine once: a rare GPU/WebKitGTK rendering failure then falls back to software rendering.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b33","slug":"reference-troubleshooting-and-recovery","text":"A graph will not finish opening","title":"Reference/Troubleshooting and recovery"},{"anchor":"b34","slug":"reference-troubleshooting-and-recovery","text":"Meaning: Tine started, but the open itself is stuck or has failed. Once it takes longer than a moment you get a card naming the current phase and the elapsed time; if the open cannot complete, the same card becomes Tine needs help opening this workspace with actions.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b35","slug":"reference-troubleshooting-and-recovery","text":"1. Retry lookup — attempt the same open again. This is safe to repeat.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b36","slug":"reference-troubleshooting-and-recovery","text":"2. Open another graph… — pick a different folder and leave this one untouched.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b37","slug":"reference-troubleshooting-and-recovery","text":"3. Return … to Direct Files… — offered only for a graph you enrolled in experimental Tine-managed storage; it puts that graph back on plain files.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b38","slug":"reference-troubleshooting-and-recovery","text":"4. Copy details — copies the phase and error text for an issue report. Use this before anything else if you plan to report it.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b39","slug":"reference-troubleshooting-and-recovery","text":"5. What you should see: no managed-storage data has been discarded by the failure. Retrying, choosing another graph, or closing and relaunching Tine are all safe to try before any manual recovery.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b40","slug":"reference-troubleshooting-and-recovery","text":"Create a privacy-safe diagnostic report","title":"Reference/Troubleshooting and recovery"},{"anchor":"b41","slug":"reference-troubleshooting-and-recovery","text":"1. Open Settings → Diagnostics and choose Create diagnostic report. Tine previews its bounded current-and-previous-run flight recorder: fixed operation names, outcomes, timings, counts, platform, version, and build information.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b42","slug":"reference-troubleshooting-and-recovery","text":"2. Review the JSON, then choose Copy report (or Save report… on desktop). Nothing is uploaded automatically. The recorder excludes graph content, paths, page titles, queries, URLs, credentials, and the opt-in detailed debug log.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b43","slug":"reference-troubleshooting-and-recovery","text":"3. For a suspected Syncthing/Dropbox mismatch, use Verify synchronized graph in the same tab on both devices, exchange the generated reports, and compare them. This check includes paths and page names but never note contents.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b44","slug":"reference-troubleshooting-and-recovery","text":"4. What you should see: a report you can attach to an issue without first setting up adb, SSH, or a terminal. Clear recorded events removes the retained flight-recorder history after you are done.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b45","slug":"reference-troubleshooting-and-recovery","text":"Something parses or renders wrong","title":"Reference/Troubleshooting and recovery"},{"anchor":"b46","slug":"reference-troubleshooting-and-recovery","text":"1. Open Settings → Help improve Tine: Tine runs its own parser and Logseq's parser over your graph, locally, and lists every place they disagree plus a parse-speed comparison.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b47","slug":"reference-troubleshooting-and-recovery","text":"2. Copy the report shown there — every snippet is anonymized (page names and words are scrubbed, markup shape kept) and re-verified to still reproduce the divergence before it is shown. Nothing is uploaded.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b48","slug":"reference-troubleshooting-and-recovery","text":"3. What you should see: a local report, including the Tine version, that you can paste into an issue.","title":"Reference/Troubleshooting and recovery"},{"anchor":"b0","slug":"start-bring-an-existing-graph","text":"Bring an existing graph","title":"Start/Bring an existing graph"},{"anchor":"b1","slug":"start-bring-an-existing-graph","text":"Tine works directly on the same Markdown/Org files as Logseq — no import, no export, no lock-in. This Direct files mode is the normal mode; the separate, known-buggy storage & sync opt-in is documented at Features/Managed sync.","title":"Start/Bring an existing graph"},{"anchor":"b2","slug":"start-bring-an-existing-graph","text":"Open your graph","title":"Start/Bring an existing graph"},{"anchor":"b3","slug":"start-bring-an-existing-graph","text":"1. On the Welcome screen, choose Open an existing graph and pick the graph's top-level folder — usually the one containing pages/, journals/, and logseq/.","title":"Start/Bring an existing graph"},{"anchor":"b4","slug":"start-bring-an-existing-graph","text":"2. Later, use the graph-name menu at the top of the left sidebar → Open graph…, or Settings (t s) → Graph → Open another graph…. Graphs you have opened appear in the same sidebar menu for one-click switching.","title":"Start/Bring an existing graph"},{"anchor":"b5","slug":"start-bring-an-existing-graph","text":"3. From the command line, tine /path/to/graph (or TINE_GRAPH=/path/to/graph) opens a graph directly.","title":"Start/Bring an existing graph"},{"anchor":"b6","slug":"start-bring-an-existing-graph","text":"4. What you should see: the same pages and journals Logseq finds. Existing Markdown and Org pages may be at the graph root or in nested folders, not only under pages/ and journals/.","title":"Start/Bring an existing graph"},{"anchor":"b7","slug":"start-bring-an-existing-graph","text":"What Tine reads","title":"Start/Bring an existing graph"},{"anchor":"b8","slug":"start-bring-an-existing-graph","text":"The usual layout is pages/, journals/, assets/, and logseq/config.edn, but Tine also finds eligible .md, .markdown, and .org pages elsewhere inside the graph.","title":"Start/Bring an existing graph"},{"anchor":"b9","slug":"start-bring-an-existing-graph","text":"Root-level and nested pages are named from their file names and save back to their exact existing paths. Tine skips hidden/internal trees, assets, publish output, and sync-provider conflict copies.","title":"Start/Bring an existing graph"},{"anchor":"b10","slug":"start-bring-an-existing-graph","text":"Your journal settings are honored: Tine reads the journal date formats from config.edn, so old files are recognized and new journals are created in your format.","title":"Start/Bring an existing graph"},{"anchor":"b11","slug":"start-bring-an-existing-graph","text":"An Org file Tine cannot reproduce byte-for-byte opens read-only rather than being rewritten imperfectly.","title":"Start/Bring an existing graph"},{"anchor":"b12","slug":"start-bring-an-existing-graph","text":"What Tine writes","title":"Start/Bring an existing graph"},{"anchor":"b13","slug":"start-bring-an-existing-graph","text":"Edits save automatically into the same file each page came from, preserving that file's exact formatting; files with no changes are not rewritten.","title":"Start/Bring an existing graph"},{"anchor":"b14","slug":"start-bring-an-existing-graph","text":"New pages and journals are ordinary .md or .org files in the configured pages and journals folders (Settings → Editor → File format chooses what new files use).","title":"Start/Bring an existing graph"},{"anchor":"b15","slug":"start-bring-an-existing-graph","text":"A Tine view (grid, table, board) attaches harmless tine.* properties to its own block; Logseq shows them as ordinary property lines — see Features/Sheets.","title":"Start/Bring an existing graph"},{"anchor":"b16","slug":"start-bring-an-existing-graph","text":"Coexisting with other tools","title":"Start/Bring an existing graph"},{"anchor":"b17","slug":"start-bring-an-existing-graph","text":"While Tine is open, it watches the files, so changes made by Logseq, another editor, or a sync tool appear automatically.","title":"Start/Bring an existing graph"},{"anchor":"b18","slug":"start-bring-an-existing-graph","text":"Avoid editing the same graph in two apps at once. A second Tine window on the same graph is refused; concurrent edits across other apps or devices are handled as conflicts, not assumed safe.","title":"Start/Bring an existing graph"},{"anchor":"b19","slug":"start-bring-an-existing-graph","text":"If a page changes on disk while you have unsaved edits, Tine overwrites nothing — a banner offers Use disk version and Keep mine (overwrite). The mechanics are in Reference/Files, external edits, and backups.","title":"Start/Bring an existing graph"},{"anchor":"b20","slug":"start-bring-an-existing-graph","text":"Syncthing and Dropbox keep working on the folder as before; Tine detects their conflict copies and helps you merge them — also in Reference/Files, external edits, and backups.","title":"Start/Bring an existing graph"},{"anchor":"b21","slug":"start-bring-an-existing-graph","text":"First safety checks","title":"Start/Bring an existing graph"},{"anchor":"b22","slug":"start-bring-an-existing-graph","text":"1. Confirm you opened the graph root: Settings (t s) → Graph shows the current graph path. In a standard Logseq graph, this is the folder containing pages/, journals/, and logseq/config.edn.","title":"Start/Bring an existing graph"},{"anchor":"b23","slug":"start-bring-an-existing-graph","text":"2. Skim Reference/Files, external edits, and backups now — know where snapshots, conflict copies, and the trash live before you need them.","title":"Start/Bring an existing graph"},{"anchor":"b24","slug":"start-bring-an-existing-graph","text":"3. What you should see: no conflict banner, your existing pages in their original locations, and edits from Tine landing in the same files Logseq reads.","title":"Start/Bring an existing graph"},{"anchor":"b25","slug":"start-bring-an-existing-graph","text":"Where next","title":"Start/Bring an existing graph"},{"anchor":"b26","slug":"start-bring-an-existing-graph","text":"Start/Where things are maps the page, sidebars, tabs, and Settings and Help you will meet on the way; Workflows/Capture and plan your day starts the journal-first daily flow.","title":"Start/Bring an existing graph"},{"anchor":"b0","slug":"start-where-things-are","text":"Where things are","title":"Start/Where things are"},{"anchor":"b1","slug":"start-where-things-are","text":"A short map of Tine's main places, so the recipes in this Guide make sense on first read: the page in the middle, the left sidebar, the tab strip, the right sidebar, and Settings and Help. Each place links to the workflow that teaches it — nothing here is a rulebook.","title":"Start/Where things are"},{"anchor":"b2","slug":"start-where-things-are","text":"The middle: one route per pane","title":"Start/Where things are"},{"anchor":"b3","slug":"start-where-things-are","text":"Each pane shows the page or PDF its active tab points to. Tine opens on the journal feed — one continuous, editable list of days — and the Journals item in the left sidebar always takes you back to it.","title":"Start/Where things are"},{"anchor":"b4","slug":"start-where-things-are","text":"Everything you write is a block (one bullet). Blocks nest under other blocks to form the outline, and any block can carry a task, a date, a link, or its own id for references from elsewhere.","title":"Start/Where things are"},{"anchor":"b5","slug":"start-where-things-are","text":"Press Ctrl+K at any time to jump to a page by name or to text inside any block.","title":"Start/Where things are"},{"anchor":"b6","slug":"start-where-things-are","text":"The left sidebar: your graph's contents","title":"Start/Where things are"},{"anchor":"b7","slug":"start-where-things-are","text":"At the very top sits the workspace switcher — saved window layouts, covered in Workflows/Keep context visible. Just under it, the graph-name menu switches between the graphs Tine knows, with Open graph… and New graph… beside them — on desktop, Shift-click a graph row to open it in a second window instead of switching this one.","title":"Start/Where things are"},{"anchor":"b8","slug":"start-where-things-are","text":"Below the menu: Journals, then fold-up Favorites, Recent, All pages, and the Namespaces tree, where Project/Roadmap nests under Project. Favorites and Recent remember per graph whether you left them open or folded.","title":"Start/Where things are"},{"anchor":"b9","slug":"start-where-things-are","text":"Favorites can be arranged without changing what Logseq sees: choose + New group, rename the plain-text label, then drag favorites or groups left/right to lift or nest them to any depth. Deleting a group keeps everything it held one level up. Tine stores that richer arrangement on an ordinary editable page while keeping config.edn :favorites as Logseq's flat list; Workflows/Find and revisit walks the safe path.","title":"Start/Where things are"},{"anchor":"b10","slug":"start-where-things-are","text":"The + New page button at the bottom opens the same Ctrl+K box; a name that matches nothing becomes a page you can create. Press t l to fold the whole sidebar away, and t l again to bring it back.","title":"Start/Where things are"},{"anchor":"b11","slug":"start-where-things-are","text":"The tab strip: what's open","title":"Start/Where things are"},{"anchor":"b12","slug":"start-where-things-are","text":"Every open page or PDF keeps a tab along the top, browser-style: click to switch, Ctrl+W to close. Middle-click anything that opens a page — a link, a search result, a bullet's dot — to park it in a background tab without leaving this one. PDF links open in a companion pane by default, and their tabs can be dragged between panes like page tabs. Tabs come back after a restart.","title":"Start/Where things are"},{"anchor":"b13","slug":"start-where-things-are","text":"Tabs are a desktop feature — the mobile app hides the strip so one page or PDF route keeps the screen, with Back returning through its history.","title":"Start/Where things are"},{"anchor":"b14","slug":"start-where-things-are","text":"The right sidebar: parked context","title":"Start/Where things are"},{"anchor":"b15","slug":"start-where-things-are","text":"Anything you want beside the current page rather than instead of it — another page, or zoomed into one bullet — goes to the right sidebar: Shift-click a link or a bullet's dot. Items there are live editors, not previews. Press t r to show or hide the whole sidebar.","title":"Start/Where things are"},{"anchor":"b16","slug":"start-where-things-are","text":"Settings and Help","title":"Start/Where things are"},{"anchor":"b17","slug":"start-where-things-are","text":"The gear at the top right (or press t s) opens Settings: appearance, editor behavior, graph files and backups, and the remappable shortcut list.","title":"Start/Where things are"},{"anchor":"b18","slug":"start-where-things-are","text":"The ? button at the bottom right (or press Shift+?) opens Help: this Guide, the shortcut reference, and links out to release notes and bug reports.","title":"Start/Where things are"},{"anchor":"b19","slug":"start-where-things-are","text":"On a phone","title":"Start/Where things are"},{"anchor":"b20","slug":"start-where-things-are","text":"Below a 640 px window width, either sidebar opens as an overlay on top of the current route instead of shrinking it — tap the shaded outside edge, press Esc, or use Android Back to dismiss. Split panes and the tab strip are desktop-only.","title":"Start/Where things are"},{"anchor":"b21","slug":"start-where-things-are","text":"Reference/Platforms and mobile separates narrow-window behavior from native-app behavior and maps each platform's shipping surface.","title":"Start/Where things are"},{"anchor":"b22","slug":"start-where-things-are","text":"Where next","title":"Start/Where things are"},{"anchor":"b23","slug":"start-where-things-are","text":"New here? Welcome to Tine walks the first hands-on minutes. To put these places to work — parking, pinning, splitting, and saving the layout — continue with Workflows/Keep context visible; Features/Tips & shortcuts is the compact shortcut map.","title":"Start/Where things are"},{"anchor":"b0","slug":"tine-guide","text":"Tine Guide","title":"Tine Guide"},{"anchor":"b1","slug":"tine-guide","text":"Open this Guide beside your own graph when you want live examples without switching graphs.","title":"Tine Guide"},{"anchor":"b2","slug":"tine-guide","text":"Each page is read-only here. Use Copy the guide into your graph on any Guide page when you want an editable, interlinked sandbox under tine-guide/.","title":"Tine Guide"},{"anchor":"b3","slug":"tine-guide","text":"Start","title":"Tine Guide"},{"anchor":"b4","slug":"tine-guide","text":"Welcome to Tine — tour the basics hands-on: bullets, tasks, rich text, links, and live block references.","title":"Tine Guide"},{"anchor":"b5","slug":"tine-guide","text":"Start/Where things are — map the main places: the page, the left sidebar, tabs, the right sidebar, and Settings and Help.","title":"Tine Guide"},{"anchor":"b6","slug":"tine-guide","text":"Start/Bring an existing graph — point Tine at your existing Logseq graph and learn what it reads and writes.","title":"Tine Guide"},{"anchor":"b7","slug":"tine-guide","text":"Project/Roadmap — try a few example tasks for your first steps.","title":"Tine Guide"},{"anchor":"b8","slug":"tine-guide","text":"Workflows","title":"Tine Guide"},{"anchor":"b9","slug":"tine-guide","text":"Workflows/Keep context visible — park a source in the right sidebar, keep places in tabs and panes, and save the layout as a workspace.","title":"Tine Guide"},{"anchor":"b10","slug":"tine-guide","text":"Workflows/Structure repeated information — turn a small repeated outline into a table or board, then find and reuse its blocks before reaching for query syntax.","title":"Tine Guide"},{"anchor":"b11","slug":"tine-guide","text":"Workflows/Capture and plan your day — journal-first daily flow: tasks, priorities, dates, the agenda, and carrying leftovers forward.","title":"Tine Guide"},{"anchor":"b12","slug":"tine-guide","text":"Workflows/Find and revisit — jump back to anything with Ctrl+K, follow links and reference panels, and keep a search as an ordinary page.","title":"Tine Guide"},{"anchor":"b13","slug":"tine-guide","text":"Workflows/Research a document — bring in a PDF, highlight it, and tie the highlights into your notes beside the source.","title":"Tine Guide"},{"anchor":"b14","slug":"tine-guide","text":"Workflows/Extend Tine — install a plugin or theme, see exactly what authority it receives, and disable or remove it safely.","title":"Tine Guide"},{"anchor":"b15","slug":"tine-guide","text":"Features/Sheets — create grids, tables, boards, queries, and formulas over ordinary bullets.","title":"Tine Guide"},{"anchor":"b16","slug":"tine-guide","text":"Features/Formulas — build read-only computed columns with the visual formula editor.","title":"Tine Guide"},{"anchor":"b17","slug":"tine-guide","text":"Features/Quick capture — set up a global capture box (desktop) that files notes into your graph.","title":"Tine Guide"},{"anchor":"b18","slug":"tine-guide","text":"Features/PDF annotation — highlight PDFs and turn those highlights into linked note blocks.","title":"Tine Guide"},{"anchor":"b19","slug":"tine-guide","text":"Feature reference","title":"Tine Guide"},{"anchor":"b20","slug":"tine-guide","text":"Features/Plugins — install capability-limited extensions and token themes, review what they request, and keep them under your control.","title":"Tine Guide"},{"anchor":"b21","slug":"tine-guide","text":"Features/Managed sync — understand the separate, known-buggy opt-in that can add operation-backed sync while keeping your Markdown/Org graph in place.","title":"Tine Guide"},{"anchor":"b22","slug":"tine-guide","text":"Features/Tips & shortcuts — learn Ctrl+K, slash commands, tabs, sidebars, focus mode, and daily shortcuts.","title":"Tine Guide"},{"anchor":"b23","slug":"tine-guide","text":"Reference/Files, external edits, and backups — learn what Tine writes where, and where snapshots, conflict copies, and the trash live.","title":"Tine Guide"},{"anchor":"b24","slug":"tine-guide","text":"Reference/Troubleshooting and recovery — follow numbered recovery steps for conflict banners, deleted pages, snapshots, sync copies, duplicate days, and bad starts.","title":"Tine Guide"},{"anchor":"b25","slug":"tine-guide","text":"Reference/Journals, tasks, and scheduling — map journal setup, task markers and priorities, scheduling dates, the agenda, time tracking, and repeating tasks.","title":"Tine Guide"},{"anchor":"b26","slug":"tine-guide","text":"Reference/Pages, links, references, and search — the exact rules for pages, links, tags, aliases, block references, reference panels, and every search surface.","title":"Tine Guide"},{"anchor":"b27","slug":"tine-guide","text":"Reference/Platforms and mobile — learn what changes on a narrow window versus on the Android app, and what ships on each platform today.","title":"Tine Guide"},{"anchor":"b28","slug":"tine-guide","text":"Feature showcase","title":"Tine Guide"},{"anchor":"b29","slug":"tine-guide","text":"Feature showcase — inspect one live example of each supported Logseq rendering feature.","title":"Tine Guide"},{"anchor":"b30","slug":"tine-guide","text":"Create one yourself","title":"Tine Guide"},{"anchor":"b31","slug":"tine-guide","text":"1. Open one of the Guide pages above and follow its numbered steps.","title":"Tine Guide"},{"anchor":"b32","slug":"tine-guide","text":"2. Use Copy the guide into your graph when you want an editable sandbox.","title":"Tine Guide"},{"anchor":"b33","slug":"tine-guide","text":"3. Tine creates the real tine-guide/ namespace, rewrites guide links to that copy, and leaves existing copied pages untouched.","title":"Tine Guide"},{"anchor":"b34","slug":"tine-guide","text":"4. What you should see: normal Logseq pages you can edit, delete, or keep as a reference.","title":"Tine Guide"},{"anchor":"b0","slug":"welcome-to-tine","text":"Welcome to Tine 👋","title":"Welcome to Tine"},{"anchor":"b1","slug":"welcome-to-tine","text":"Tine is a fast, local outliner that reads and writes the same Markdown/Org files as Logseq — the very folder you point it at. Edit here or in Logseq; it's one graph, no import, no export. We have a lot of respect for Logseq — Tine just tries to improve a few things.","title":"Welcome to Tine"},{"anchor":"b2","slug":"welcome-to-tine","text":"Everything you see here is a real Markdown file in this graph's pages/ folder. Open that folder in your file manager and look — nothing is locked away.","title":"Welcome to Tine"},{"anchor":"b3","slug":"welcome-to-tine","text":"Try the basics right now","title":"Welcome to Tine"},{"anchor":"b4","slug":"welcome-to-tine","text":"Click any bullet to edit it. Enter makes a new bullet, Tab indents, Shift+Tab outdents. Drag a bullet's dot to move it (and everything under it).","title":"Welcome to Tine"},{"anchor":"b5","slug":"welcome-to-tine","text":"Tasks — type TODO / DOING / DONE at the start of a bullet, or press Ctrl+Enter to cycle one:","title":"Welcome to Tine"},{"anchor":"b6","slug":"welcome-to-tine","text":"Click this checkbox to complete me","title":"Welcome to Tine"},{"anchor":"b7","slug":"welcome-to-tine","text":"This one is already done","title":"Welcome to Tine"},{"anchor":"b8","slug":"welcome-to-tine","text":"Rich text: bold, italic, highlight, inline code, and even math like e^{i\\pi} + 1 = 0.","title":"Welcome to Tine"},{"anchor":"b9","slug":"welcome-to-tine","text":"Links: type [[ to link a page or # for a #tag. Here's a link to Project/Roadmap — click it.","title":"Welcome to Tine"},{"anchor":"b10","slug":"welcome-to-tine","text":"Block references & embeds","title":"Welcome to Tine"},{"anchor":"b11","slug":"welcome-to-tine","text":"Every bullet has a hidden id, so you can point at one specific bullet from anywhere. This is a live reference to a bullet over on the Roadmap:","title":"Welcome to Tine"},{"anchor":"b12","slug":"welcome-to-tine","text":"And here is that same bullet embedded inline — it stays in sync with the original:","title":"Welcome to Tine"},{"anchor":"b14","slug":"welcome-to-tine","text":"Keep exploring","title":"Welcome to Tine"},{"anchor":"b15","slug":"welcome-to-tine","text":"Tine Guide — open the in-app how-to guide beside your own graph, with live examples you can copy into a sandbox.","title":"Welcome to Tine"},{"anchor":"b16","slug":"welcome-to-tine","text":"Start/Where things are — a map of the main places: the page, the sidebars, tabs, and Settings and Help.","title":"Welcome to Tine"},{"anchor":"b17","slug":"welcome-to-tine","text":"Features/Quick capture — on desktop, drop a thought into your graph from any app with a global hotkey. (Set this one up — it's genuinely good.)","title":"Welcome to Tine"},{"anchor":"b18","slug":"welcome-to-tine","text":"Features/Tips & shortcuts — slash commands, the command palette, tabs, the sidebar, focus mode and dimming.","title":"Welcome to Tine"},{"anchor":"b19","slug":"welcome-to-tine","text":"Features/Sheets — grids, field tables, and task boards over plain bullets.","title":"Welcome to Tine"},{"anchor":"b20","slug":"welcome-to-tine","text":"Features/PDF annotation — highlight PDFs and turn them into linked notes.","title":"Welcome to Tine"},{"anchor":"b21","slug":"welcome-to-tine","text":"Features/Plugins — add small capability-limited extensions or token themes without giving code unrestricted access to Tine.","title":"Welcome to Tine"},{"anchor":"b22","slug":"welcome-to-tine","text":"Features/Managed sync — learn about the separate, opt-in, known-buggy mode for operation-backed sync that keeps your Markdown/Org graph in place.","title":"Welcome to Tine"},{"anchor":"b23","slug":"welcome-to-tine","text":"When you're ready, point Tine at your own Logseq graph: open Settings (t s) and pick a different folder — Start/Bring an existing graph walks you through it. Your notes stay exactly where they are.","title":"Welcome to Tine"},{"anchor":"b0","slug":"workflows-capture-and-plan-your-day","text":"Capture and plan your day","title":"Workflows/Capture and plan your day"},{"anchor":"b1","slug":"workflows-capture-and-plan-your-day","text":"The shortest path: open Journals in the sidebar and start typing. Everything below adds one tool at a time — a task marker, a priority, a date — and ends with the two things that keep a plan current: the Agenda and carry-over.","title":"Workflows/Capture and plan your day"},{"anchor":"b2","slug":"workflows-capture-and-plan-your-day","text":"Describe your day in bullets","title":"Workflows/Capture and plan your day"},{"anchor":"b3","slug":"workflows-capture-and-plan-your-day","text":"1. Click Journals in the sidebar — the feed opens with today first. Click into today's first bullet and type what happened or what you mean to do.","title":"Workflows/Capture and plan your day"},{"anchor":"b4","slug":"workflows-capture-and-plan-your-day","text":"2. Press Enter for the next bullet, Tab / Shift+Tab to nest or flatten it.","title":"Workflows/Capture and plan your day"},{"anchor":"b5","slug":"workflows-capture-and-plan-your-day","text":"3. What you should see: the text saves to today's journal file on its own — there is no Save button. For where writes go and what happens if a file changes on disk, see Reference/Files, external edits, and backups.","title":"Workflows/Capture and plan your day"},{"anchor":"b6","slug":"workflows-capture-and-plan-your-day","text":"Not at your desk? Quick capture","title":"Workflows/Capture and plan your day"},{"anchor":"b7","slug":"workflows-capture-and-plan-your-day","text":"When a thought arrives while you are in another app, press your desktop quick-capture shortcut, type, and the note is appended to today's journal without switching windows. One-time setup, the optional page-title field, and the Enter-key tuning are all in Features/Quick capture.","title":"Workflows/Capture and plan your day"},{"anchor":"b8","slug":"workflows-capture-and-plan-your-day","text":"Turn a bullet into a task","title":"Workflows/Capture and plan your day"},{"anchor":"b9","slug":"workflows-capture-and-plan-your-day","text":"1. With the caret anywhere in a bullet, press Ctrl+Enter (Cmd on Mac). The bullet becomes TODO …; press again for DOING, again for DONE, once more to drop the marker. (Under the NOW / LATER workflow the cycle is LATER → NOW → DONE.)","title":"Workflows/Capture and plan your day"},{"anchor":"b10","slug":"workflows-capture-and-plan-your-day","text":"2. Prefer the mouse? Click the marker chip to toggle between the workflow's two open states (TODO ↔ DOING or LATER ↔ NOW), or click the checkbox in front of the task to finish it in one step.","title":"Workflows/Capture and plan your day"},{"anchor":"b11","slug":"workflows-capture-and-plan-your-day","text":"3. Select several blocks first and the same keypress cycles every selected task at once.","title":"Workflows/Capture and plan your day"},{"anchor":"b12","slug":"workflows-capture-and-plan-your-day","text":"4. What you should see: a colored marker chip at the start of the block, plus an empty checkbox until the task is done.","title":"Workflows/Capture and plan your day"},{"anchor":"b13","slug":"workflows-capture-and-plan-your-day","text":"Rank it","title":"Workflows/Capture and plan your day"},{"anchor":"b14","slug":"workflows-capture-and-plan-your-day","text":"Type / and choose Priority A (or B, C) — the marker line becomes TODO [#A] Call the bank.","title":"Workflows/Capture and plan your day"},{"anchor":"b15","slug":"workflows-capture-and-plan-your-day","text":"What you should see: a colored [#A] chip right after the marker; swap it by running the command again.","title":"Workflows/Capture and plan your day"},{"anchor":"b16","slug":"workflows-capture-and-plan-your-day","text":"Give it a date","title":"Workflows/Capture and plan your day"},{"anchor":"b17","slug":"workflows-capture-and-plan-your-day","text":"1. Type / and choose Scheduled, then pick the day in the calendar popup — use Add time if the hour matters.","title":"Workflows/Capture and plan your day"},{"anchor":"b18","slug":"workflows-capture-and-plan-your-day","text":"2. Add Deadline the same way when the task has a hard due date.","title":"Workflows/Capture and plan your day"},{"anchor":"b19","slug":"workflows-capture-and-plan-your-day","text":"3. What you should see: a small calendar chip next to the block for each date. Click a chip any time to change or remove it.","title":"Workflows/Capture and plan your day"},{"anchor":"b20","slug":"workflows-capture-and-plan-your-day","text":"Try it: from bullets to an open-task query","title":"Workflows/Capture and plan your day"},{"anchor":"b21","slug":"workflows-capture-and-plan-your-day","text":"Copy this Guide into your graph and look at these example tasks:","title":"Workflows/Capture and plan your day"},{"anchor":"b22","slug":"workflows-capture-and-plan-your-day","text":"Collect the audit receipts","title":"Workflows/Capture and plan your day"},{"anchor":"b23","slug":"workflows-capture-and-plan-your-day","text":"Book the flights","title":"Workflows/Capture and plan your day"},{"anchor":"b24","slug":"workflows-capture-and-plan-your-day","text":"Read the harvest notes","title":"Workflows/Capture and plan your day"},{"anchor":"b25","slug":"workflows-capture-and-plan-your-day","text":"Water the office plants","title":"Workflows/Capture and plan your day"},{"anchor":"b26","slug":"workflows-capture-and-plan-your-day","text":"Then this query lists them:","title":"Workflows/Capture and plan your day"},{"anchor":"b28","slug":"workflows-capture-and-plan-your-day","text":"What you should see: the marked tasks above, plus tasks elsewhere in the graph that use TODO, DOING, NOW, or LATER (the Feature showcase has a few; a copied Guide adds your own). The query scans the whole graph for those four markers; DONE tasks and tasks using other markers do not appear.","title":"Workflows/Capture and plan your day"},{"anchor":"b29","slug":"workflows-capture-and-plan-your-day","text":"See the plan: the Agenda","title":"Workflows/Capture and plan your day"},{"anchor":"b30","slug":"workflows-capture-and-plan-your-day","text":"1. Scroll to the bottom of today's journal: the Scheduled &amp; Deadline list shows open items whose date is near today, wherever in the graph they were written.","title":"Workflows/Capture and plan your day"},{"anchor":"b31","slug":"workflows-capture-and-plan-your-day","text":"2. What you should see: your dated tasks, each with its date chip; click one to jump to it. Widen or narrow the range in Settings → Journals → Agenda window (default: a week back and a week ahead).","title":"Workflows/Capture and plan your day"},{"anchor":"b32","slug":"workflows-capture-and-plan-your-day","text":"Carry-over: let unfinished tasks follow you","title":"Workflows/Capture and plan your day"},{"anchor":"b33","slug":"workflows-capture-and-plan-your-day","text":"1. Scroll to a past day in the feed and click Carry unfinished tasks → today under its title. Blocks with open markers move to today; DONE and CANCELED stay put.","title":"Workflows/Capture and plan your day"},{"anchor":"b34","slug":"workflows-capture-and-plan-your-day","text":"2. What you should see: a \"Carried N items to today\" toast — or \"No unfinished tasks to carry\" if none were open.","title":"Workflows/Capture and plan your day"},{"anchor":"b35","slug":"workflows-capture-and-plan-your-day","text":"3. Variants: on today, Carry from previous day pulls yesterday in; Carry last N days goes further back (N is set in Settings, default 7). The same action is on a journal's right-click menu, and the command palette (Ctrl+Shift+P) has 7 / 30 / 365-day presets.","title":"Workflows/Capture and plan your day"},{"anchor":"b36","slug":"workflows-capture-and-plan-your-day","text":"Settings → Journals also tunes it: hide the buttons (the right-click menu keeps working), move the whole block with its context or just the task line, add a “Carried over” heading.","title":"Workflows/Capture and plan your day"},{"anchor":"b37","slug":"workflows-capture-and-plan-your-day","text":"Where everything lives","title":"Workflows/Capture and plan your day"},{"anchor":"b38","slug":"workflows-capture-and-plan-your-day","text":"All of this remains plain text. Journal entries use the graph's configured journal directory; tasks on ordinary pages stay in their own Markdown or Org files. Within a task, the marker comes first, then [#A], then the SCHEDULED:/DEADLINE: lines — readable by Logseq and by any editor. The companion reference page Reference/Journals, tasks, and scheduling maps the marker set, repeaters, time tracking, and the stored query behind the Agenda. If something looks wrong — a banner, a conflict copy, a duplicate day — Reference/Troubleshooting and recovery has the recovery steps.","title":"Workflows/Capture and plan your day"},{"anchor":"b0","slug":"workflows-extend-tine","text":"Extend Tine","title":"Workflows/Extend Tine"},{"anchor":"b1","slug":"workflows-extend-tine","text":"Add a plugin or a theme in a few minutes, know exactly what authority you granted, and take it back cleanly. This page is the hands-on path; the detailed rulebook stays on Features/Plugins.","title":"Workflows/Extend Tine"},{"anchor":"b2","slug":"workflows-extend-tine","text":"Know what a plugin can touch before you install one","title":"Workflows/Extend Tine"},{"anchor":"b3","slug":"workflows-extend-tine","text":"Tine plugins are capability-limited WebAssembly guests. They are not Logseq or Obsidian plugins, and plugins written for those apps do not run here.","title":"Workflows/Extend Tine"},{"anchor":"b4","slug":"workflows-extend-tine","text":"The plugin API is experimental. An app update may leave an incompatible plugin installed but disabled; it must not make your graph unreadable or discard the plugin's local settings.","title":"Workflows/Extend Tine"},{"anchor":"b5","slug":"workflows-extend-tine","text":"A plugin declares capabilities from a short, closed list, and Tine performs each one on its behalf: command-palette actions, slash commands, small block decorations (thread lines, badges), declarative settings, and narrowly preconditioned edits to a focused block.","title":"Workflows/Extend Tine"},{"anchor":"b6","slug":"workflows-extend-tine","text":"A plugin cannot access the DOM, Tauri, the network, files, processes, or your graph directly, and it cannot inject HTML or CSS — everything it shows is drawn by Tine. The one capability that can change your text is graph.write.block, and even it may edit only the block Tine handed the plugin, recording normal undo and saving through the same conflict-checked path your own edits use.","title":"Workflows/Extend Tine"},{"anchor":"b7","slug":"workflows-extend-tine","text":"Install one — it starts disabled","title":"Workflows/Extend Tine"},{"anchor":"b8","slug":"workflows-extend-tine","text":"1. Open Settings (t s) → Plugins → Browse. Each community-catalogue entry lists its source, license, supported platforms, and declared capabilities, plus a safety verdict — from \"Low-risk automated pass\" up to \"Human-reviewed before publication\" (Tine holds every plugin that can edit text for human review). Open its Safety report for the digest-verified detail, and keep the reminder under it in mind: automated review is evidence, not a guarantee.","title":"Workflows/Extend Tine"},{"anchor":"b9","slug":"workflows-extend-tine","text":"2. Choose Install. Nothing runs yet — every plugin version is installed disabled, and Tine takes you to the Installed tab with its details open.","title":"Workflows/Extend Tine"},{"anchor":"b10","slug":"workflows-extend-tine","text":"3. Review what it claims: name, version, author, license, platforms, capabilities. If they match what you expected, flip the toggle to enable it.","title":"Workflows/Extend Tine"},{"anchor":"b11","slug":"workflows-extend-tine","text":"4. Developing or sideloading instead? Install a local package takes a manifest.json and its .wasm file together — with the same installed-disabled rule.","title":"Workflows/Extend Tine"},{"anchor":"b12","slug":"workflows-extend-tine","text":"What you should see: exactly the contribution the plugin declared — a command-palette entry, a slash command, or a decoration — and nothing else. If the package does not support your device, its button reads Unavailable on … instead of Install.","title":"Workflows/Extend Tine"},{"anchor":"b13","slug":"workflows-extend-tine","text":"Change its settings — Tine's controls, your device","title":"Workflows/Extend Tine"},{"anchor":"b14","slug":"workflows-extend-tine","text":"A plugin that declares settings gets a Settings section on its details page, but Tine draws the controls — toggles, dropdowns, numbers, text — from the plugin's declared schema. Values are validated scalars, stored on this device only and never written into your graph. A changed key offers Reset; Reset all settings restores the schema defaults.","title":"Workflows/Extend Tine"},{"anchor":"b15","slug":"workflows-extend-tine","text":"Disable it, or take it out","title":"Workflows/Extend Tine"},{"anchor":"b16","slug":"workflows-extend-tine","text":"Flip the same toggle to disable: the behavior stops, the package stays installed, and your pages remain exactly as readable as before — a plugin may not invent a format your graph would depend on.","title":"Workflows/Extend Tine"},{"anchor":"b17","slug":"workflows-extend-tine","text":"Uninstall… removes only that package version from this device. Tine asks first and states the boundary: it does not change your graph or notes.","title":"Workflows/Extend Tine"},{"anchor":"b18","slug":"workflows-extend-tine","text":"Behind the scenes, cached signed revocations are checked before a saved plugin starts, so a version revoked as unsafe stays disabled even while you are offline.","title":"Workflows/Extend Tine"},{"anchor":"b19","slug":"workflows-extend-tine","text":"Themes change presentation; they never run","title":"Workflows/Extend Tine"},{"anchor":"b20","slug":"workflows-extend-tine","text":"Themes live separately under Settings → Appearance. Style controls typography, journal headings, and other Tine-owned presentation styles; Color scheme selects Default, Nord, Solarized, Gruvbox, or the colors from an installed package. Style and colors are independent, so you can keep notnote's editorial style while using Gruvbox colors. Declarative packages install from the Theme packages list or a local .json file and contain no scripts, selectors, imports, downloaded fonts, or remote assets. The choices stay on this device, and no theme ever reads or writes your graph.","title":"Workflows/Extend Tine"},{"anchor":"b21","slug":"workflows-extend-tine","text":"A Today summary, when selected, is rendered by Tine from the journal page already on screen: it counts open task markers there and calls the DOING, NOW, STARTED, and IN-PROGRESS subset “in progress.” The theme receives neither those tasks nor a query interface.","title":"Workflows/Extend Tine"},{"anchor":"b22","slug":"workflows-extend-tine","text":"Your own logseq/custom.css outranks every theme: themes recolor Tine through Logseq's --ls-* variables, and your CSS loads last. Uninstalling a theme package leaves it untouched, too.","title":"Workflows/Extend Tine"},{"anchor":"b23","slug":"workflows-extend-tine","text":"Platform and distribution lines","title":"Workflows/Extend Tine"},{"anchor":"b24","slug":"workflows-extend-tine","text":"Desktop and Android share the same plugin and theme lifecycle; a package that did not declare your platform shows as unavailable rather than failing later.","title":"Workflows/Extend Tine"},{"anchor":"b25","slug":"workflows-extend-tine","text":"The F-Droid build is planned, not distributed today; F-Droid builds omit the network community catalogue to comply with the store's runtime-code-download policy. The plugin host, your already-installed plugins and themes, local manifest.json + .wasm and theme packages, and the built-in gallery all keep working there.","title":"Workflows/Extend Tine"},{"anchor":"b26","slug":"workflows-extend-tine","text":"Current public releases do not include an iOS app, and the iOS plugin host is not enabled. Reference/Platforms and mobile carries the full platform map.","title":"Workflows/Extend Tine"},{"anchor":"b27","slug":"workflows-extend-tine","text":"Where next","title":"Workflows/Extend Tine"},{"anchor":"b28","slug":"workflows-extend-tine","text":"Features/Plugins keeps the detailed reference, including the safety-report fields and the cascade order — and links the authoring, packaging, and registry guide used by plugin developers.","title":"Workflows/Extend Tine"},{"anchor":"b0","slug":"workflows-find-and-revisit","text":"Find and revisit","title":"Workflows/Find and revisit"},{"anchor":"b1","slug":"workflows-find-and-revisit","text":"Three moves cover most of finding things: jump to what you remember, follow the trail of links, and keep a search that's worth keeping. No syntax is needed up front. The exact rules live in Reference/Pages, links, references, and search.","title":"Workflows/Find and revisit"},{"anchor":"b2","slug":"workflows-find-and-revisit","text":"\"I saw it somewhere\" — jump with Ctrl+K","title":"Workflows/Find and revisit"},{"anchor":"b3","slug":"workflows-find-and-revisit","text":"1. Press Ctrl+K (Cmd on Mac) and type any words from the title or the text you remember. The switcher matches page titles and the visible text of blocks — not hidden properties or ids.","title":"Workflows/Find and revisit"},{"anchor":"b4","slug":"workflows-find-and-revisit","text":"2. Too many hits? Narrow with the Search syntax forms listed in the switcher footer: -draft excludes a word, OR offers alternatives, quotes pin an exact phrase, /…/ is a case-sensitive regular expression.","title":"Workflows/Find and revisit"},{"anchor":"b5","slug":"workflows-find-and-revisit","text":"3. Enter opens the highlighted result; Shift+Enter opens it in the right sidebar beside your current page; middle-click a result for a background tab.","title":"Workflows/Find and revisit"},{"anchor":"b6","slug":"workflows-find-and-revisit","text":"4. Sure it's on the open page? Ctrl+Shift+K searches only that page's blocks, including the ones folded away, and Ctrl+F is the slim in-page find bar with match counts.","title":"Workflows/Find and revisit"},{"anchor":"b7","slug":"workflows-find-and-revisit","text":"What you should see: Tine jumps to the page or block. Exact title matches lead the list; over time Tine may prefer a result you deliberately picked before, but only among equally strong matches — Settings → Editor → Learn Ctrl+K choices resets or disables that.","title":"Workflows/Find and revisit"},{"anchor":"b8","slug":"workflows-find-and-revisit","text":"Follow the trail: links, tags, and references","title":"Workflows/Find and revisit"},{"anchor":"b9","slug":"workflows-find-and-revisit","text":"1. Click any [[link]] or #tag to open its page. A dimmed, dotted-underlined link isn't broken — opening it creates the page. While editing, Ctrl+O follows the link at the caret and Ctrl+Shift+O opens it in the right sidebar.","title":"Workflows/Find and revisit"},{"anchor":"b10","slug":"workflows-find-and-revisit","text":"2. On the page you reach, scroll to Linked References: every block that points here — busy pages group them by source — with a chip filter to narrow to blocks that also mention something else. Open Unlinked References to catch plain-text mentions you never linked.","title":"Workflows/Find and revisit"},{"anchor":"b11","slug":"workflows-find-and-revisit","text":"3. Need several references outside Tine? Use the copy/export button on Linked References or Unlinked References. Every visible entry starts selected; uncheck a subset, then use the ordinary Text / OPML / HTML export choices. Linked References honors the text and chip filters already applied.","title":"Workflows/Find and revisit"},{"anchor":"b12","slug":"workflows-find-and-revisit","text":"4. Found a line worth quoting in your own note? Edit the note, type ((, and search the line's text to insert a block reference — a live copy that updates whenever the original changes.","title":"Workflows/Find and revisit"},{"anchor":"b13","slug":"workflows-find-and-revisit","text":"What you should see: the reference renders as link-styled text with the source's current words, and the source block gains a small reference-count badge that lists its referrers.","title":"Workflows/Find and revisit"},{"anchor":"b14","slug":"workflows-find-and-revisit","text":"Keep what matters close: Favorites","title":"Workflows/Find and revisit"},{"anchor":"b15","slug":"workflows-find-and-revisit","text":"1. Favorite a page from its title menu. It appears under Favorites in the left sidebar and remains in Logseq's ordinary flat config.edn :favorites list.","title":"Workflows/Find and revisit"},{"anchor":"b16","slug":"workflows-find-and-revisit","text":"2. Choose + New group, type a plain-text name, and drag a favorite onto it. Drag right to nest under the preceding row, left to lift out, or vertically to reorder without changing depth. Groups and favorites can both contain children.","title":"Workflows/Find and revisit"},{"anchor":"b17","slug":"workflows-find-and-revisit","text":"3. Collapse any row that has children. Delete a group when you no longer need the label: what it held moves up one level and stays favorited.","title":"Workflows/Find and revisit"},{"anchor":"b18","slug":"workflows-find-and-revisit","text":"4. Prefer the keyboard, or need to resolve a sync edit? Open the arrangement page Tine created. A bullet that is exactly one [[page link]] is a favorite; any other bullet is a label. Editing, nesting, adding, or removing those bullets updates the sidebar immediately.","title":"Workflows/Find and revisit"},{"anchor":"b19","slug":"workflows-find-and-revisit","text":"What you should see: the richer tree follows page renames and syncs as an ordinary graph page, while Logseq continues to read the same flat favorites membership. Tine does not create the arrangement page until you make a group or nest a row.","title":"Workflows/Find and revisit"},{"anchor":"b20","slug":"workflows-find-and-revisit","text":"Keep the search: make a search tab","title":"Workflows/Find and revisit"},{"anchor":"b21","slug":"workflows-find-and-revisit","text":"1. From any Ctrl+K search, press Open search tab in the footer. The whole search becomes its own tab with its own search box — nothing is written to your graph yet, and the tab comes back after a restart.","title":"Workflows/Find and revisit"},{"anchor":"b22","slug":"workflows-find-and-revisit","text":"2. Refine it there: switch Search / List / Table / Board freely — that changes only how results are shown, never which blocks matched. Open Filters / Advanced for fields and date ranges, or Edit as visual query to build filters chip by chip; Explain query describes what Tine understood.","title":"Workflows/Find and revisit"},{"anchor":"b23","slug":"workflows-find-and-revisit","text":"3. Worth keeping? Type a name into Name this search to save it as a page and press Save page.","title":"Workflows/Find and revisit"},{"anchor":"b24","slug":"workflows-find-and-revisit","text":"4. What you should see: the tab becomes an ordinary page in your graph holding one query block. You can link to it, favorite it, and its results refresh themselves; an existing page with the same name is never overwritten.","title":"Workflows/Find and revisit"},{"anchor":"b25","slug":"workflows-find-and-revisit","text":"Try it: find every mention of one page","title":"Workflows/Find and revisit"},{"anchor":"b26","slug":"workflows-find-and-revisit","text":"1. Text search finds visible words. A page query asks a different question: \"which blocks connect to Project/Roadmap?\" — written as the page's name inside a query, like this live example:","title":"Workflows/Find and revisit"},{"anchor":"b28","slug":"workflows-find-and-revisit","text":"2. What you should see in a copied Guide or the public demo: the Roadmap outline itself (a block always counts its own page, and a nested bullet counts whatever its parents mention), the bullets elsewhere in the Guide that link there — Welcome to Tine has one — and this numbered bullet, which links too. In this read-only Guide the same block runs against your own graph instead, so it lists your pages' mentions — often nothing yet; it comes alive after you copy the Guide into your graph.","title":"Workflows/Find and revisit"},{"anchor":"b29","slug":"workflows-find-and-revisit","text":"Where next","title":"Workflows/Find and revisit"},{"anchor":"b30","slug":"workflows-find-and-revisit","text":"The exact rules — ranking, search scope, saved-page behavior — are mapped in Reference/Pages, links, references, and search. For turning found or structured blocks into tables and boards, see Workflows/Structure repeated information; the wider shortcut map is Features/Tips & shortcuts.","title":"Workflows/Find and revisit"},{"anchor":"b0","slug":"workflows-keep-context-visible","text":"Keep context visible","title":"Workflows/Keep context visible"},{"anchor":"b1","slug":"workflows-keep-context-visible","text":"Source beside draft, note beside plan: this tour builds a working layout step by step — park a page in the right sidebar, collect places in tabs, split the window for true side-by-side, and save the arrangement as a workspace. Each part ends with what you should see. The shortcut map is Features/Tips & shortcuts.","title":"Workflows/Keep context visible"},{"anchor":"b2","slug":"workflows-keep-context-visible","text":"Park a source in the right sidebar","title":"Workflows/Keep context visible"},{"anchor":"b3","slug":"workflows-keep-context-visible","text":"1. On the page you're writing, Shift-click a link (or a bullet's dot) to open it in the right sidebar. It's a full editor, not a preview — you can write in either place.","title":"Workflows/Keep context visible"},{"anchor":"b4","slug":"workflows-keep-context-visible","text":"2. Two more ways to park things: in Ctrl+K, press Shift+Enter on any page or block result; while editing, Ctrl+Shift+O sends the link at the caret across.","title":"Workflows/Keep context visible"},{"anchor":"b5","slug":"workflows-keep-context-visible","text":"3. Crowded? Fold an item with its arrow and keep just its title in reach, or use the sidebar's ⋯ menu for Collapse all, Expand all, and Close all. Folding or closing never strands half-typed text — Tine commits the active edit first.","title":"Workflows/Keep context visible"},{"anchor":"b6","slug":"workflows-keep-context-visible","text":"4. Press t r to hide the whole sidebar and t r again to bring it back just as it was; its items are restored with your session.","title":"Workflows/Keep context visible"},{"anchor":"b7","slug":"workflows-keep-context-visible","text":"What you should see: the source parked beside your page, both editable — and it stays parked while the main page navigates elsewhere.","title":"Workflows/Keep context visible"},{"anchor":"b8","slug":"workflows-keep-context-visible","text":"Gather places in tabs, and pin the ones you live in","title":"Workflows/Keep context visible"},{"anchor":"b9","slug":"workflows-keep-context-visible","text":"1. Middle-click a link, a search hit, or a bullet's dot to open it in a background tab — you never leave the page you're on.","title":"Workflows/Keep context visible"},{"anchor":"b10","slug":"workflows-keep-context-visible","text":"2. Navigating to a page that's already open just focuses its tab instead of making a duplicate (Settings → Editor → Switch to an already-open tab when navigating turns that off).","title":"Workflows/Keep context visible"},{"anchor":"b11","slug":"workflows-keep-context-visible","text":"3. Double-click a tab to pin it. Pinned tabs gather at the left and hold their content: ordinary navigation from one opens a fresh tab instead, and closing a pinned tab asks first — an accidental Ctrl+W can't eat it.","title":"Workflows/Keep context visible"},{"anchor":"b12","slug":"workflows-keep-context-visible","text":"4. Closed one too soon? Ctrl+Shift+T reopens the last closed tab with its history. When titles stop fitting, the ⌄ Show all tabs button at the strip's edge lists them in full — activate, pin, close, or drag to reorder there.","title":"Workflows/Keep context visible"},{"anchor":"b13","slug":"workflows-keep-context-visible","text":"What you should see: the same tabs, pins included, come back after a restart — and as session state outside your graph, none of this ever adds a file to it.","title":"Workflows/Keep context visible"},{"anchor":"b14","slug":"workflows-keep-context-visible","text":"Split the window for true side-by-side","title":"Workflows/Keep context visible"},{"anchor":"b15","slug":"workflows-keep-context-visible","text":"1. Desktop only: Ctrl+click (Cmd on Mac) any [[link]], tag, or block reference to open it in another pane — with a single pane, Tine splits right for it. In Ctrl+K, Alt+Enter does the same for the highlighted result. The direct bindings: Ctrl+Alt+\\ splits right with a copy of the current tab, Ctrl+Alt+Shift+\\ splits down.","title":"Workflows/Keep context visible"},{"anchor":"b16","slug":"workflows-keep-context-visible","text":"2. Each pane keeps its own tab strip and its own back/forward history — Alt+Left and Alt+Right step through it, even mid-edit.","title":"Workflows/Keep context visible"},{"anchor":"b17","slug":"workflows-keep-context-visible","text":"3. Drag the seam between panes to resize them. Drag a tab onto another pane's strip to move it there, onto a pane's body to append it, or onto a seam or pane edge to split that spot and drop the tab into the new pane — Esc cancels a drag mid-way.","title":"Workflows/Keep context visible"},{"anchor":"b18","slug":"workflows-keep-context-visible","text":"4. PDF readers use the same tabs and panes. Opening a PDF link makes a companion pane while preserving the source page; you can then drag the PDF tab into any pane or quadrant. Notes opens the PDF's notes page in its structural companion pane, and that notes tab can be moved in exactly the same way.","title":"Workflows/Keep context visible"},{"anchor":"b19","slug":"workflows-keep-context-visible","text":"5. From the keyboard, Ctrl+1 … Ctrl+9 focus panes in reading order, Ctrl+Alt+←↑↓→ moves focus to the nearest pane in that direction, and Ctrl+Alt+Shift+←↑↓→ moves the active tab there instead. Moving the last tab out of a pane closes the emptied pane; a journals feed keeps its last tab.","title":"Workflows/Keep context visible"},{"anchor":"b20","slug":"workflows-keep-context-visible","text":"6. Prefer staged control? Esc climbs from editing to block selection into pane-select mode — a hint pill at the bottom tells you when it's on. Arrows step between panes, seams, and window edges; Enter on a seam makes a mirror split; typing opens the new pane with the search box pre-filled. Another Esc backs out.","title":"Workflows/Keep context visible"},{"anchor":"b21","slug":"workflows-keep-context-visible","text":"What you should see: two note panes that scroll, navigate, and keep tabs independently — source and draft side by side, never fighting over one cursor.","title":"Workflows/Keep context visible"},{"anchor":"b22","slug":"workflows-keep-context-visible","text":"Save the arrangement as a workspace","title":"Workflows/Keep context visible"},{"anchor":"b23","slug":"workflows-keep-context-visible","text":"1. With the layout where you want it — splits, every pane's tabs and histories, both sidebars — click the workspace name at the top of the left sidebar and choose + New workspace; name it once.","title":"Workflows/Keep context visible"},{"anchor":"b24","slug":"workflows-keep-context-visible","text":"2. Come back to it from the same switcher: hover the name for a quick-switch list, or click it for the full menu with Rename and Delete. Each graph keeps its own set, and the active one comes back after a restart.","title":"Workflows/Keep context visible"},{"anchor":"b25","slug":"workflows-keep-context-visible","text":"What you should see: the saved pane layout, tabs and histories, sidebars, and Recent return together. Workspaces are device-local session state — saving, switching, or deleting one never writes to your graph.","title":"Workflows/Keep context visible"},{"anchor":"b26","slug":"workflows-keep-context-visible","text":"Clear everything else away","title":"Workflows/Keep context visible"},{"anchor":"b27","slug":"workflows-keep-context-visible","text":"t f (focus mode) hides the sidebars and toolbar so the screen is just text — on desktop it also takes the window full screen. Hover the top edge to reach the toolbar again; layered Esc steps back out.","title":"Workflows/Keep context visible"},{"anchor":"b28","slug":"workflows-keep-context-visible","text":"t b fades every block except the one you're editing. Settings → Appearance → Dim in focus mode can dim for you while focus mode is on — without rewriting your manual t b choice.","title":"Workflows/Keep context visible"},{"anchor":"b29","slug":"workflows-keep-context-visible","text":"On a phone the layout stays one page: the sidebars open as overlays (dismiss with the shaded edge, Esc, or Android Back), and tabs and splits are desktop-only. A PDF and its Notes page use that same history, so Back returns to the previous surface.","title":"Workflows/Keep context visible"},{"anchor":"b30","slug":"workflows-keep-context-visible","text":"Where next","title":"Workflows/Keep context visible"},{"anchor":"b31","slug":"workflows-keep-context-visible","text":"Features/Tips & shortcuts has the compact shortcut map, Start/Where things are is the plain map of the places used here, and Workflows/Find and revisit covers getting back to anything you parked.","title":"Workflows/Keep context visible"},{"anchor":"b0","slug":"workflows-research-a-document","text":"Research a document","title":"Workflows/Research a document"},{"anchor":"b1","slug":"workflows-research-a-document","text":"The short path: drop a PDF onto a page, read it in a companion pane, and highlight as you go. Each highlight becomes an ordinary bullet you can write under, quote anywhere, and follow back to the exact spot — so a paper turns into linked, searchable notes without leaving Tine. The precise highlight and storage rules live in Features/PDF annotation.","title":"Workflows/Research a document"},{"anchor":"b2","slug":"workflows-research-a-document","text":"Bring the document in","title":"Workflows/Research a document"},{"anchor":"b3","slug":"workflows-research-a-document","text":"1. Drag a PDF from your file manager onto any page and drop it on a block — or paste one you copied, or run the /Upload an asset slash command. Tine stores the file in your graph's assets/ folder and inserts a link where you dropped it.","title":"Workflows/Research a document"},{"anchor":"b4","slug":"workflows-research-a-document","text":"2. Click the inserted link. On desktop the document opens as a normal tab in a companion pane beside your notes. Drag the shared seam to resize it, or drag the PDF tab to another pane, seam, or pane edge to move it or make a split. On a phone it opens in the current one-pane history, and Back returns to the source page.","title":"Workflows/Research a document"},{"anchor":"b5","slug":"workflows-research-a-document","text":"What you should see: the PDF in an ordinary pane, with a toolbar holding a page-number box, a find button (Ctrl+F searches inside the document), zoom controls, an Area highlight toggle, a Notes button, Outline, a ⋯ menu, and the close control at the far edge.","title":"Workflows/Research a document"},{"anchor":"b6","slug":"workflows-research-a-document","text":"Read and highlight","title":"Workflows/Research a document"},{"anchor":"b7","slug":"workflows-research-a-document","text":"1. Select a passage with the mouse and pick a color in the menu that appears — that's a highlight. Click an existing highlight to reopen its menu: recolor it, or remove it with ✕.","title":"Workflows/Research a document"},{"anchor":"b8","slug":"workflows-research-a-document","text":"2. To clip a figure or table instead, toggle Area highlight in the toolbar (or hold Shift on Linux/Windows, Command on macOS) and drag a rectangle over the region, then choose its color. Dismiss the color menu and nothing is written.","title":"Workflows/Research a document"},{"anchor":"b9","slug":"workflows-research-a-document","text":"3. Long document? Outline navigates its table of contents, the page-number box jumps straight to a page, and the ⋯ menu offers a persistent Light, Warm, or Dark reader theme — remembered on this device, not written into your graph.","title":"Workflows/Research a document"},{"anchor":"b10","slug":"workflows-research-a-document","text":"What you should see: colored marks on the document — and, behind each mark, a bullet on a notes page named after the PDF.","title":"Workflows/Research a document"},{"anchor":"b11","slug":"workflows-research-a-document","text":"Turn highlights into notes","title":"Workflows/Research a document"},{"anchor":"b12","slug":"workflows-research-a-document","text":"1. Press Notes in the reader toolbar. On desktop Tine opens the document's highlights page in the structural companion pane next to the PDF; move its tab if another pane is more useful. On a phone it opens in the same history, so Back returns to the PDF. The page is listed under the document's plain name (its page name starts with hls__, like Logseq), and every highlight is a bullet marked with a colored dot.","title":"Workflows/Research a document"},{"anchor":"b13","slug":"workflows-research-a-document","text":"2. Write under a highlight bullet: a summary, a question, your own structure. These are ordinary bullets on an ordinary graph page — edit, nest, tag, and search them like any others.","title":"Workflows/Research a document"},{"anchor":"b14","slug":"workflows-research-a-document","text":"3. Click the colored dot on a highlight bullet (or the highlight itself back in the PDF) to jump between the two: each note goes straight back to its spot in the document.","title":"Workflows/Research a document"},{"anchor":"b15","slug":"workflows-research-a-document","text":"What you should see: your notes and their source passages stay connected in both directions, and recoloring a highlight updates its dot on the notes page to match.","title":"Workflows/Research a document"},{"anchor":"b16","slug":"workflows-research-a-document","text":"Quote a passage in your ordinary notes","title":"Workflows/Research a document"},{"anchor":"b17","slug":"workflows-research-a-document","text":"1. Click the highlight and choose Copy ref (on desktop), then paste into any bullet in your own notes. The pasted ((…)) renders as link-styled text quoting the highlighted passage, and clicking the quote opens the document at that page.","title":"Workflows/Research a document"},{"anchor":"b18","slug":"workflows-research-a-document","text":"2. Keep source and words visible while you write: the PDF is a normal tab, so it can sit in any resizable pane or quadrant next to your notes page; Shift-click on any bullet's dot parks that note in the right sidebar. On a phone the reader instead fills the width of the screen and the sidebars open as overlays — the two-up layout is a wider-window pattern.","title":"Workflows/Research a document"},{"anchor":"b19","slug":"workflows-research-a-document","text":"3. Choose Linked references on the highlight's menu (also on desktop) to list every note that quotes it — the trail from one passage to everywhere you used it.","title":"Workflows/Research a document"},{"anchor":"b20","slug":"workflows-research-a-document","text":"What you should see: your note cites the source live, not as a copied excerpt — touch nothing, and the quote still opens the PDF at the right page tomorrow.","title":"Workflows/Research a document"},{"anchor":"b21","slug":"workflows-research-a-document","text":"Share the result","title":"Workflows/Research a document"},{"anchor":"b22","slug":"workflows-research-a-document","text":"1. From the notes page title's right-click menu (or its ⋯ menu): Copy page as Markdown puts a clean outline on the clipboard, Copy / export as… offers a rendered copy, and Export to PDF… prints the whole page through your OS print dialog — always on a light background, whatever your theme.","title":"Workflows/Research a document"},{"anchor":"b23","slug":"workflows-research-a-document","text":"2. Publishing on the web? Pages marked public:: true are included in the static HTML export (Settings → Graph → Export graph to HTML).","title":"Workflows/Research a document"},{"anchor":"b24","slug":"workflows-research-a-document","text":"Your annotations are stored Logseq-compatibly — the hls__ page with your notes, an .edn sidecar and any clipped area images under assets/ — so launch snapshots cover your notes, config, and PDF highlights (not media files), and another Logseq-compatible tool reads the same annotations.","title":"Workflows/Research a document"},{"anchor":"b25","slug":"workflows-research-a-document","text":"Where next","title":"Workflows/Research a document"},{"anchor":"b26","slug":"workflows-research-a-document","text":"The exact highlight, merge, and storage rules are mapped in Features/PDF annotation. For quoting anything else with ((…)) and the reference panels, see Workflows/Find and revisit; for snapshots and backups, Reference/Files, external edits, and backups.","title":"Workflows/Research a document"},{"anchor":"b0","slug":"workflows-structure-repeated-information","text":"Structure repeated information","title":"Workflows/Structure repeated information"},{"anchor":"b1","slug":"workflows-structure-repeated-information","text":"Start with the bullets you already write. Add a few fields when they become useful, then choose a table or board to see the same blocks from a different angle.","title":"Workflows/Structure repeated information"},{"anchor":"b2","slug":"workflows-structure-repeated-information","text":"A small project tracker","title":"Workflows/Structure repeated information"},{"anchor":"b3","slug":"workflows-structure-repeated-information","text":"Refresh the Guide examples","title":"Workflows/Structure repeated information"},{"anchor":"b4","slug":"workflows-structure-repeated-information","text":"Decide the next topic","title":"Workflows/Structure repeated information"},{"anchor":"b5","slug":"workflows-structure-repeated-information","text":"Publish the updated demo","title":"Workflows/Structure repeated information"},{"anchor":"b6","slug":"workflows-structure-repeated-information","text":"Turn child bullets into a view","title":"Workflows/Structure repeated information"},{"anchor":"b7","slug":"workflows-structure-repeated-information","text":"1. Make a parent bullet like the tracker above, then add ordinary child bullets for each item.","title":"Workflows/Structure repeated information"},{"anchor":"b8","slug":"workflows-structure-repeated-information","text":"2. Right-click the parent and choose Show children as → Table (or type /Table). Use + Add column to add fields such as Status, Owner, and Estimate; edit their values in the cells.","title":"Workflows/Structure repeated information"},{"anchor":"b9","slug":"workflows-structure-repeated-information","text":"3. When progress matters more than rows, type /Board on that parent. Choose Group by and select Status to make one column per status.","title":"Workflows/Structure repeated information"},{"anchor":"b10","slug":"workflows-structure-repeated-information","text":"4. What you should see: the same child bullets appear as editable table rows or status columns. Move a board card to change that block's grouping field; return to the outline and the change is there too.","title":"Workflows/Structure repeated information"},{"anchor":"b11","slug":"workflows-structure-repeated-information","text":"Find and reuse the same kind of block","title":"Workflows/Structure repeated information"},{"anchor":"b12","slug":"workflows-structure-repeated-information","text":"1. Press Ctrl+K, then search for Refresh Guide examples. The friendly search surface finds that tracker block without needing a query expression.","title":"Workflows/Structure repeated information"},{"anchor":"b13","slug":"workflows-structure-repeated-information","text":"2. Choose Open search tab. There, choose Filters / Advanced, then Edit as visual query. In the chip bar, use ➕ Add filter → Property to choose Owner and the value Avery.","title":"Workflows/Structure repeated information"},{"anchor":"b14","slug":"workflows-structure-repeated-information","text":"3. Choose Table or Board in the result presentation controls. The selection answers which blocks to show; the view answers how to show them, so you can change the presentation without remaking the selection.","title":"Workflows/Structure repeated information"},{"anchor":"b15","slug":"workflows-structure-repeated-information","text":"4. What you should see: a reusable selection of matching tracker blocks, first as search results and then as the table or board you chose.","title":"Workflows/Structure repeated information"},{"anchor":"b16","slug":"workflows-structure-repeated-information","text":"Query-backed board of the same tracker","title":"Workflows/Structure repeated information"},{"anchor":"b18","slug":"workflows-structure-repeated-information","text":"This board finds the matching tracker bullets above; it does not copy them. Inspect it here, in a copied Guide, or in the public demo, then change its view with the visual controls.","title":"Workflows/Structure repeated information"},{"anchor":"b19","slug":"workflows-structure-repeated-information","text":"What is stored, only when you need to inspect it","title":"Workflows/Structure repeated information"},{"anchor":"b20","slug":"workflows-structure-repeated-information","text":"The view-owning parent carries tine.view:: table or tine.view:: board; the optional tine.fields:: line declares the columns and their types. The child bullets remain the source blocks with their ordinary properties.","title":"Workflows/Structure repeated information"},{"anchor":"b21","slug":"workflows-structure-repeated-information","text":"The query-backed example stores {{query (property owner Avery)}} to choose its blocks, while its tine.view:: board and tine.group-by:: status lines choose the presentation. The visual builder and friendly search lead here without requiring you to type the DSL.","title":"Workflows/Structure repeated information"},{"anchor":"b22","slug":"workflows-structure-repeated-information","text":"Optional: add a derived field","title":"Workflows/Structure repeated information"},{"anchor":"b23","slug":"workflows-structure-repeated-information","text":"If Estimate needs a computed companion, add a formula from the table header. For the visual formula editor, its read-only results, and the raw-expression escape hatch, use Features/Formulas. For table, board, and query-view details, return to Features/Sheets.","title":"Workflows/Structure repeated information"}];
